/**
 * Основная база данных приложения
 */
@Database(
    entities = [UserEntity::class, ExerciseResultEntity::class],
    version = 1,
    exportSchema = false
)
@TypeConverters(Converters::class)
abstract class AppDatabase : RoomDatabase() {
    abstract fun userDao(): UserDao
    abstract fun exerciseResultDao(): ExerciseResultDao

    companion object {
        const val DATABASE_NAME = "danabala_database"
    }
