/** * Репозиторий для работы с упражнениями и результатами */ interface ExerciseRepository { suspend fun getExercisesByType(type: ExerciseType): Flow<List<Exercise>> suspend fun getExercisesByGrade(grade: Grade): Flow<List<Exercise>> suspend fun getExerciseById(id: String): Result<Exercise?> suspend fun saveExerciseResult(result: ExerciseResult): Result<Unit> suspend fun getUserResults(userId: String): Flow<List<ExerciseResult>> suspend fun getUserResultsForExercise(userId: String, exerciseId: String): Flow<List<ExerciseResult>> }

package com.example.danabala.domain.repository
import com.example.danabala.domain.model.User import kotlinx.coroutines.flow.Flow
/** * Репозиторий для работы с пользователями */ interface UserRepository { suspend fun createUser(user: User): Result<Unit> suspend fun getUserById(id: String): Result<User?> suspend fun getAllUsers(): Flow<List<User>> suspend fun updateUser(user: User): Result<Unit> suspend fun deleteUser(id: String): Result<Unit> suspend fun getCurrentUser(): Flow<User?> suspend fun setCurrentUser(userId: String): Result<Unit> }

