package com.timursarsembayev.danabalanumbers

import android.animation.AnimatorSet
import android.animation.ObjectAnimator
import android.content.ClipData
import android.content.Intent
import android.os.Bundle
import android.speech.tts.TextToSpeech
import android.view.DragEvent
import android.view.MotionEvent
import android.view.View
import android.widget.LinearLayout
import android.widget.ProgressBar
import android.widget.TextView
import android.widget.Button
import android.widget.ImageButton
import androidx.appcompat.app.AppCompatActivity
import androidx.core.content.ContextCompat
import androidx.core.view.ViewCompat
import androidx.core.view.WindowInsetsCompat
import java.util.*
import kotlin.random.Random

class AscendingSequenceActivity : AppCompatActivity(), TextToSpeech.OnInitListener {

    private var tts: TextToSpeech? = null
    private var currentQuestion = 0
    private var score = 0
    private var totalCorrectAnswers = 0
    private val totalQuestions = 20
    private var hasTriedCurrentQuestion = false

    // UI элементы
    private lateinit var progressBar: ProgressBar
    private lateinit var questionText: TextView
    private lateinit var dropZones: List<TextView>
    private lateinit var checkButton: Button
    private lateinit var nextButton: Button
    private lateinit var hintText: TextView
    private lateinit var draggableContainer: LinearLayout

    // Логика игры
    private var sequenceSize = 5
    private var shownPosition = 0 // позиция видимого числа (0-4)
    private var shownNumber = 0 // показанное число
    private var startNumber = 0 // начальное число последовательности
    private var availableNumbers = mutableListOf<Int>()
    private var userAnswers = IntArray(5) { -1 } // -1 означает пустое место

    // Варианты похвалы за правильные ответы
    private val correctPhrases = listOf(
        "Молодец!", "Так держать!", "Превосходно!", "Отлично!",
        "Замечательно!", "Ты супер!", "Великолепно!", "Браво!",
        "Умница!", "Здорово!"
    )

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_ascending_sequence)

        ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main)) { v, insets ->
            val systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars())
            v.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom)
            insets
        }

        tts = TextToSpeech(this, this)
        initializeViews()
        setupDragAndDrop()
        generateNewQuestion()
    }

    private fun initializeViews() {
        progressBar = findViewById(R.id.progressBar)
        questionText = findViewById(R.id.questionText)
        checkButton = findViewById(R.id.checkButton)
        nextButton = findViewById(R.id.nextButton)
        hintText = findViewById(R.id.hintText)
        draggableContainer = findViewById(R.id.draggableNumbersContainer)

        // Инициализируем drop zones
        dropZones = listOf(
            findViewById(R.id.dropZone1),
            findViewById(R.id.dropZone2),
            findViewById(R.id.dropZone3),
            findViewById(R.id.dropZone4),
            findViewById(R.id.dropZone5)
        )

        checkButton.setOnClickListener { checkAnswer() }
        nextButton.setOnClickListener { nextQuestion() }

        // Добавляем обработчик для кнопки "Назад"
        findViewById<ImageButton>(R.id.backButton).setOnClickListener {
            finish() // Возвращаемся к предыдущему экрану
        }

        // Изначально скрываем кнопку "Далее"
        nextButton.visibility = Button.GONE
    }

    private fun setupDragAndDrop() {
        // Настройка drop zones
        dropZones.forEachIndexed { index, dropZone ->
            dropZone.setOnDragListener { view, event ->
                when (event.action) {
                    DragEvent.ACTION_DRAG_STARTED -> true
                    DragEvent.ACTION_DRAG_ENTERED -> {
                        view.setBackgroundResource(R.drawable.number_drop_zone_highlight)
                        true
                    }
                    DragEvent.ACTION_DRAG_EXITED -> {
                        resetDropZoneBackground(view as TextView, index)
                        true
                    }
                    DragEvent.ACTION_DROP -> {
                        val dragData = event.clipData.getItemAt(0).text.toString()
                        val draggedNumber = dragData.split("|")[0].toInt()
                        val sourceType = if (dragData.contains("|")) dragData.split("|")[1] else "selection"

                        handleCardDrop(view as TextView, index, draggedNumber, sourceType)
                        true
                    }
                    DragEvent.ACTION_DRAG_ENDED -> {
                        resetDropZoneBackground(view as TextView, index)
                        true
                    }
                    else -> false
                }
            }

            // Добавляем обработчик нажатия для возврата карточек
            dropZone.setOnClickListener {
                returnCardToSelection(dropZone as TextView, index)
            }

            // Добавляем возможность перетаскивания карточек между ячейками
            dropZone.setOnTouchListener { view, event ->
                if (event.action == MotionEvent.ACTION_DOWN &&
                    dropZone.text.isNotEmpty() &&
                    index != shownPosition) {
                    val number = dropZone.text.toString().toInt()
                    val clipData = ClipData.newPlainText("number", "$number|dropzone_$index")
                    val shadowBuilder = View.DragShadowBuilder(view)
                    view.startDragAndDrop(clipData, shadowBuilder, view, 0)
                    true
                } else {
                    false
                }
            }
        }

        // Настройка области выбора для приема карточек обратно
        setupSelectionAreaDropZones()
    }

    private fun setupSelectionAreaDropZones() {
        val firstRowContainer = findViewById<LinearLayout>(R.id.firstRowContainer)
        val secondRowContainer = findViewById<LinearLayout>(R.id.secondRowContainer)

        // Настраиваем первый ряд как drop zone
        firstRowContainer.setOnDragListener { view, event ->
            when (event.action) {
                DragEvent.ACTION_DRAG_STARTED -> true
                DragEvent.ACTION_DRAG_ENTERED -> {
                    // Визуальная подсветка области
                    view.setBackgroundColor(ContextCompat.getColor(this, android.R.color.holo_blue_light))
                    view.alpha = 0.3f
                    true
                }
                DragEvent.ACTION_DRAG_EXITED -> {
                    // Убираем подсветку
                    view.setBackgroundColor(android.graphics.Color.TRANSPARENT)
                    view.alpha = 1.0f
                    true
                }
                DragEvent.ACTION_DROP -> {
                    // Убираем подсветку
                    view.setBackgroundColor(android.graphics.Color.TRANSPARENT)
                    view.alpha = 1.0f

                    val dragData = event.clipData.getItemAt(0).text.toString()
                    if (dragData.contains("|dropzone_")) {
                        val draggedNumber = dragData.split("|")[0].toInt()
                        val sourceIndex = dragData.split("_")[1].toInt()
                        returnCardFromDropZone(draggedNumber, sourceIndex)
                    }
                    true
                }
                DragEvent.ACTION_DRAG_ENDED -> {
                    // Убираем подсветку на всякий случай
                    view.setBackgroundColor(android.graphics.Color.TRANSPARENT)
                    view.alpha = 1.0f
                    true
                }
                else -> false
            }
        }

        // Настраиваем второй ряд как drop zone
        secondRowContainer.setOnDragListener { view, event ->
            when (event.action) {
                DragEvent.ACTION_DRAG_STARTED -> true
                DragEvent.ACTION_DRAG_ENTERED -> {
                    view.setBackgroundColor(ContextCompat.getColor(this, android.R.color.holo_blue_light))
                    view.alpha = 0.3f
                    true
                }
                DragEvent.ACTION_DRAG_EXITED -> {
                    view.setBackgroundColor(android.graphics.Color.TRANSPARENT)
                    view.alpha = 1.0f
                    true
                }
                DragEvent.ACTION_DROP -> {
                    view.setBackgroundColor(android.graphics.Color.TRANSPARENT)
                    view.alpha = 1.0f

                    val dragData = event.clipData.getItemAt(0).text.toString()
                    if (dragData.contains("|dropzone_")) {
                        val draggedNumber = dragData.split("|")[0].toInt()
                        val sourceIndex = dragData.split("_")[1].toInt()
                        returnCardFromDropZone(draggedNumber, sourceIndex)
                    }
                    true
                }
                DragEvent.ACTION_DRAG_ENDED -> {
                    view.setBackgroundColor(android.graphics.Color.TRANSPARENT)
                    view.alpha = 1.0f
                    true
                }
                else -> false
            }
        }
    }

    private fun returnCardFromDropZone(number: Int, sourceIndex: Int) {
        // Очищаем исходную ячейку
        dropZones[sourceIndex].text = ""
        dropZones[sourceIndex].setBackgroundResource(R.drawable.number_drop_zone)
        userAnswers[sourceIndex] = -1

        // Добавляем карточку обратно в область выбора
        addCardBackToSelection(number)
    }

    private fun resetDropZoneBackground(dropZone: TextView, index: Int) {
        if (index == shownPosition) {
            dropZone.setBackgroundResource(R.drawable.number_input_shown)
        } else if (dropZone.text.isNotEmpty()) {
            dropZone.setBackgroundResource(R.drawable.number_drop_zone_filled)
        } else {
            dropZone.setBackgroundResource(R.drawable.number_drop_zone)
        }
    }

    private fun createDraggableCard(number: Int): TextView {
        val card = TextView(this).apply {
            text = number.toString()
            textSize = 20f
            setTextColor(ContextCompat.getColor(this@AscendingSequenceActivity, android.R.color.black))
            setBackgroundResource(R.drawable.draggable_number_card)
            gravity = android.view.Gravity.CENTER
            setPadding(24, 16, 24, 16)

            // Используем фиксированные размеры вместо app_icon_size
            val layoutParams = LinearLayout.LayoutParams(
                120, // ширина в пикселях (примерно 60dp)
                120  // высота в пикселях (примерно 60dp)
            ).apply {
                setMargins(8, 8, 8, 8)
            }
            this.layoutParams = layoutParams

            // Настройка drag functionality
            setOnTouchListener { view, event ->
                if (event.action == MotionEvent.ACTION_DOWN) {
                    val clipData = ClipData.newPlainText("number", number.toString())
                    val shadowBuilder = View.DragShadowBuilder(view)
                    view.startDragAndDrop(clipData, shadowBuilder, view, 0)
                    true
                } else {
                    false
                }
            }
        }
        return card
    }

    private fun removeDraggedCard(number: Int) {
        val firstRowContainer = findViewById<LinearLayout>(R.id.firstRowContainer)
        val secondRowContainer = findViewById<LinearLayout>(R.id.secondRowContainer)

        // Ищем карточку в первом ряду
        for (i in 0 until firstRowContainer.childCount) {
            val child = firstRowContainer.getChildAt(i) as TextView
            if (child.text.toString() == number.toString()) {
                firstRowContainer.removeView(child)
                return
            }
        }

        // Ищем карточку в�� втором ряду
        for (i in 0 until secondRowContainer.childCount) {
            val child = secondRowContainer.getChildAt(i) as TextView
            if (child.text.toString() == number.toString()) {
                secondRowContainer.removeView(child)
                return
            }
        }
    }

    private fun generateNewQuestion() {
        hasTriedCurrentQuestion = false
        checkButton.isEnabled = true
        nextButton.visibility = Button.GONE
        userAnswers.fill(-1)

        // Генерируем случайную позицию для показанного числа (0-4)
        shownPosition = Random.nextInt(sequenceSize)

        // Генерируем показанное число от 0 до 9
        shownNumber = Random.nextInt(10)

        // Вычисляем начальное число последовательности
        startNumber = shownNumber - shownPosition

        // Если начальное число меньше 0, корректируем
        if (startNumber < 0) {
            startNumber = 0
            shownNumber = shownPosition
        }

        // Если последовательность выходит за 9, корректируем
        if (startNumber + sequenceSize - 1 > 9) {
            startNumber = 9 - sequenceSize + 1
            shownNumber = startNumber + shownPosition
        }

        // Очищаем и настраиваем drop zones
        dropZones.forEachIndexed { index, dropZone ->
            if (index == shownPosition) {
                dropZone.text = shownNumber.toString()
                dropZone.setBackgroundResource(R.drawable.number_input_shown)
                userAnswers[index] = shownNumber
            } else {
                dropZone.text = ""
                dropZone.setBackgroundResource(R.drawable.number_drop_zone)
            }
        }

        // Создаем доступные числа для перетаскивания
        availableNumbers.clear()
        for (i in 0 until sequenceSize) {
            val number = startNumber + i
            if (number != shownNumber) { // Исключаем показанное число, а не позицию
                availableNumbers.add(number)
            }
        }

        // Добавляем несколько лишних чисел для усложнения
        val extraNumbers = mutableSetOf<Int>()
        while (extraNumbers.size < 3) {
            val extraNumber = Random.nextInt(10)
            if (extraNumber !in (startNumber until startNumber + sequenceSize)) {
                extraNumbers.add(extraNumber)
            }
        }
        availableNumbers.addAll(extraNumbers)

        // Перемешиваем числа
        availableNumbers.shuffle()

        // Создаем перетаскиваемые карточки и размещаем их по 4 в ряд
        val firstRowContainer = findViewById<LinearLayout>(R.id.firstRowContainer)
        val secondRowContainer = findViewById<LinearLayout>(R.id.secondRowContainer)

        firstRowContainer.removeAllViews()
        secondRowContainer.removeAllViews()

        availableNumbers.forEachIndexed { index, number ->
            val card = createDraggableCard(number)

            if (index < 4) {
                firstRowContainer.addView(card)
            } else {
                secondRowContainer.addView(card)
            }
        }

        updateProgress()
        updateQuestionText()
        speakQuestion()
    }

    private fun updateQuestionText() {
        questionText.text = "Заполни чи́сла по возрастанию"
        hintText.text = "Перетащи чи́сла в правильном порядке"
    }

    private fun updateProgress() {
        progressBar.progress = ((currentQuestion.toFloat() / totalQuestions) * 100).toInt()
    }

    private fun checkAnswer() {
        if (!hasTriedCurrentQuestion) {
            hasTriedCurrentQuestion = true
        }

        var allCorrect = true

        // Проверяем каждую drop zone
        dropZones.forEachIndexed { index, dropZone ->
            val correctAnswer = startNumber + index
            val userAnswer = userAnswers[index]

            if (userAnswer == correctAnswer) {
                dropZone.setBackgroundResource(R.drawable.number_input_correct)
                animateCorrectAnswer(dropZone)
            } else {
                dropZone.setBackgroundResource(R.drawable.number_input_incorrect)
                animateIncorrectAnswer(dropZone)
                allCorrect = false
            }
        }

        if (allCorrect) {
            score += 100
            totalCorrectAnswers++
            showCorrectFeedback()
            checkButton.isEnabled = false
            nextButton.visibility = Button.VISIBLE
        } else {
            showIncorrectFeedback()
        }
    }

    private fun showCorrectFeedback() {
        val phrase = correctPhrases.random()
        hintText.text = phrase
        hintText.setTextColor(ContextCompat.getColor(this, android.R.color.holo_green_dark))
        speakText(phrase)
    }

    private fun showIncorrectFeedback() {
        hintText.text = "Попробуй еще раз! Числа должны идти по порядку."
        hintText.setTextColor(ContextCompat.getColor(this, android.R.color.holo_red_dark))
        speakText("Попробуй еще раз")
    }

    private fun nextQuestion() {
        currentQuestion++

        if (currentQuestion >= totalQuestions) {
            finishGame()
        } else {
            generateNewQuestion()
        }
    }

    private fun finishGame() {
        val intent = Intent(this, AscendingSequenceResultsActivity::class.java)
        intent.putExtra("score", score)
        intent.putExtra("totalCorrectAnswers", totalCorrectAnswers)
        intent.putExtra("totalQuestions", totalQuestions)
        startActivity(intent)
        finish()
    }

    private fun animateCorrectAnswer(view: TextView) {
        val scaleX = ObjectAnimator.ofFloat(view, "scaleX", 1f, 1.2f, 1f)
        val scaleY = ObjectAnimator.ofFloat(view, "scaleY", 1f, 1.2f, 1f)
        val animatorSet = AnimatorSet()
        animatorSet.playTogether(scaleX, scaleY)
        animatorSet.duration = 300
        animatorSet.start()
    }

    private fun animateIncorrectAnswer(view: TextView) {
        val shake = ObjectAnimator.ofFloat(view, "translationX", 0f, -10f, 10f, -5f, 5f, 0f)
        shake.duration = 500
        shake.start()
    }

    private fun speakQuestion() {
        speakText("Заполни числа по возрастанию. Показано число ${shownNumber}")
    }

    private fun speakText(text: String) {
        tts?.speak(text, TextToSpeech.QUEUE_FLUSH, null, null)
    }

    override fun onInit(status: Int) {
        if (status == TextToSpeech.SUCCESS) {
            val result = tts!!.setLanguage(Locale("ru", "RU"))
            if (result == TextToSpeech.LANG_MISSING_DATA || result == TextToSpeech.LANG_NOT_SUPPORTED) {
                tts!!.setLanguage(Locale.getDefault())
            }
            // Озвучиваем вопрос после успешной инициализации TTS
            speakQuestion()
        }
    }

    override fun onDestroy() {
        tts?.stop()
        tts?.shutdown()
        super.onDestroy()
    }

    private fun returnCardToSelection(dropZone: TextView, index: Int) {
        // Проверяем, что это не стартовое число и ячейка не пустая
        if (index != shownPosition && dropZone.text.isNotEmpty()) {
            val number = dropZone.text.toString().toInt()

            // Очищаем ячейку
            dropZone.text = ""
            dropZone.setBackgroundResource(R.drawable.number_drop_zone)
            userAnswers[index] = -1

            // Возвращаем карточку в блок выбора
            addCardBackToSelection(number)
        }
    }

    private fun addCardBackToSelection(number: Int) {
        val firstRowContainer = findViewById<LinearLayout>(R.id.firstRowContainer)
        val secondRowContainer = findViewById<LinearLayout>(R.id.secondRowContainer)

        // Создаем новую карточку
        val card = createDraggableCard(number)

        // Добавляем в первый ряд, если там меньше 4 карточек, иначе во второй
        if (firstRowContainer.childCount < 4) {
            firstRowContainer.addView(card)
        } else {
            secondRowContainer.addView(card)
        }
    }

    private fun handleCardDrop(dropZone: TextView, index: Int, draggedNumber: Int, sourceType: String) {
        // Если это защищенная ячейка с показанным числом, не позволяем ничего делать
        if (index == shownPosition) {
            return
        }

        // Если карточка перетаскивается из области выбора
        if (sourceType == "selection") {
            // Если ячейка уже занята, возвращаем предыдущую карточку в область выбора
            if (dropZone.text.isNotEmpty()) {
                val previousNumber = dropZone.text.toString().toInt()
                addCardBackToSelection(previousNumber)
            }

            // Размещаем новую карточку
            dropZone.text = draggedNumber.toString()
            dropZone.setBackgroundResource(R.drawable.number_drop_zone_filled)
            userAnswers[index] = draggedNumber

            // Удаляем использованную карточку из области выбора
            removeDraggedCard(draggedNumber)
        }
        // Если карточка перетаскивается из другой ячейки
        else if (sourceType.startsWith("dropzone_")) {
            val sourceIndex = sourceType.split("_")[1].toInt()

            // Если ячейка назначения пустая - просто перемещаем
            if (dropZone.text.isEmpty()) {
                dropZone.text = draggedNumber.toString()
                dropZone.setBackgroundResource(R.drawable.number_drop_zone_filled)
                userAnswers[index] = draggedNumber

                // Очищаем исходную ячейку
                dropZones[sourceIndex].text = ""
                dropZones[sourceIndex].setBackgroundResource(R.drawable.number_drop_zone)
                userAnswers[sourceIndex] = -1
            }
            // Если ячейка назначения занята - меняем карточки местами
            else {
                val targetNumber = dropZone.text.toString().toInt()

                // Выполняем обмен карточками
                dropZone.text = draggedNumber.toString()
                dropZones[sourceIndex].text = targetNumber.toString()

                // Обновляем массив ответов
                userAnswers[index] = draggedNumber
                userAnswers[sourceIndex] = targetNumber

                // Обновляем фоны
                dropZone.setBackgroundResource(R.drawable.number_drop_zone_filled)
                dropZones[sourceIndex].setBackgroundResource(R.drawable.number_drop_zone_filled)
            }
        }
    }
}

package com.timursarsembayev.danabalanumbers

import android.animation.AnimatorSet
import android.animation.ObjectAnimator
import android.content.ClipData
import android.content.Context
import android.content.Intent
import android.os.Bundle
import android.speech.tts.TextToSpeech
import android.view.DragEvent
import android.view.MotionEvent
import android.view.View
import android.widget.LinearLayout
import android.widget.ProgressBar
import android.widget.TextView
import android.widget.Button
import android.widget.ImageButton
import androidx.appcompat.app.AppCompatActivity
import androidx.core.content.ContextCompat
import androidx.core.view.ViewCompat
import androidx.core.view.WindowInsetsCompat
import java.util.*
import kotlin.random.Random

class AscendingSequenceActivity : AppCompatActivity(), TextToSpeech.OnInitListener {

    private var tts: TextToSpeech? = null
    private var currentQuestion = 0
    private var score = 0
    private var totalCorrectAnswers = 0
    private val totalQuestions = 20
    private var hasTriedCurrentQuestion = false

    // UI элементы
    private lateinit var progressBar: ProgressBar
    private lateinit var questionText: TextView
    private lateinit var dropZones: List<TextView>
    private lateinit var checkButton: Button
    private lateinit var nextButton: Button
    private lateinit var hintText: TextView
    private lateinit var draggableContainer: LinearLayout

    // Логика игры
    private var sequenceSize = 5
    private var shownPosition = 0 // позиция видимого числа (0-4)
    private var shownNumber = 0 // показанное число
    private var startNumber = 0 // начальное число последовательности
    private var availableNumbers = mutableListOf<Int>()
    private var userAnswers = IntArray(5) { -1 } // -1 означает пустое место

    // Варианты похвалы за правильные ответы (из ресурсов)
    private val correctPhrases: List<String> by lazy {
        resources.getStringArray(R.array.ascending_positive_feedback).toList()
    }

    override fun attachBaseContext(newBase: Context) {
        super.attachBaseContext(LocaleManager.applyLanguage(newBase))
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_ascending_sequence)

        ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main)) { v, insets ->
            val systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars())
            v.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom)
            insets
        }

        // Инициализируем TTS только для ru/en; для kk — отключаем
        when (LocaleManager.getCurrentLanguage(this)) {
            LocaleManager.LANGUAGE_ENGLISH, LocaleManager.LANGUAGE_RUSSIAN -> {
                tts = TextToSpeech(this, this)
            }
            else -> tts = null
        }

        initializeViews()
        setupDragAndDrop()
        generateNewQuestion()
    }

    private fun initializeViews() {
        progressBar = findViewById(R.id.progressBar)
        questionText = findViewById(R.id.questionText)
        checkButton = findViewById(R.id.checkButton)
        nextButton = findViewById(R.id.nextButton)
        hintText = findViewById(R.id.hintText)
        draggableContainer = findViewById(R.id.draggableNumbersContainer)

        // Инициализируем drop zones
        dropZones = listOf(
            findViewById(R.id.dropZone1),
            findViewById(R.id.dropZone2),
            findViewById(R.id.dropZone3),
            findViewById(R.id.dropZone4),
            findViewById(R.id.dropZone5)
        )

        checkButton.setOnClickListener { checkAnswer() }
        nextButton.setOnClickListener { nextQuestion() }

        // Добавляем обработчик для кнопки "Назад"
        findViewById<ImageButton>(R.id.backButton).setOnClickListener {
            finish() // Возвращаемся к предыдущему экрану
        }

        // Изначально скрываем кнопку "Далее"
        nextButton.visibility = Button.GONE
    }

    private fun setupDragAndDrop() {
        // Настройка drop zones
        dropZones.forEachIndexed { index, dropZone ->
            dropZone.setOnDragListener { view, event ->
                when (event.action) {
                    DragEvent.ACTION_DRAG_STARTED -> true
                    DragEvent.ACTION_DRAG_ENTERED -> {
                        view.setBackgroundResource(R.drawable.number_drop_zone_highlight)
                        true
                    }
                    DragEvent.ACTION_DRAG_EXITED -> {
                        resetDropZoneBackground(view as TextView, index)
                        true
                    }
                    DragEvent.ACTION_DROP -> {
                        val dragData = event.clipData.getItemAt(0).text.toString()
                        val draggedNumber = dragData.split("|")[0].toInt()
                        val sourceType = if (dragData.contains("|")) dragData.split("|")[1] else "selection"

                        handleCardDrop(view as TextView, index, draggedNumber, sourceType)
                        true
                    }
                    DragEvent.ACTION_DRAG_ENDED -> {
                        resetDropZoneBackground(view as TextView, index)
                        true
                    }
                    else -> false
                }
            }

            // Добавляем обработчик нажатия для возврата карточек
            dropZone.setOnClickListener {
                returnCardToSelection(dropZone as TextView, index)
            }

            // Добавляем возможность перетаскивания карточек между ячейками
            dropZone.setOnTouchListener { view, event ->
                if (event.action == MotionEvent.ACTION_DOWN &&
                    dropZone.text.isNotEmpty() &&
                    index != shownPosition) {
                    val number = dropZone.text.toString().toInt()
                    val clipData = ClipData.newPlainText("number", "$number|dropzone_$index")
                    val shadowBuilder = View.DragShadowBuilder(view)
                    view.startDragAndDrop(clipData, shadowBuilder, view, 0)
                    true
                } else {
                    false
                }
            }
        }

        // Настройка области выбора для приема карточек обратно
        setupSelectionAreaDropZones()
    }

    private fun setupSelectionAreaDropZones() {
        val firstRowContainer = findViewById<LinearLayout>(R.id.firstRowContainer)
        val secondRowContainer = findViewById<LinearLayout>(R.id.secondRowContainer)

        // Настраиваем первый ряд как drop zone
        firstRowContainer.setOnDragListener { view, event ->
            when (event.action) {
                DragEvent.ACTION_DRAG_STARTED -> true
                DragEvent.ACTION_DRAG_ENTERED -> {
                    // Визуальная подсветка области
                    view.setBackgroundColor(ContextCompat.getColor(this, android.R.color.holo_blue_light))
                    view.alpha = 0.3f
                    true
                }
                DragEvent.ACTION_DRAG_EXITED -> {
                    // Убираем подсветку
                    view.setBackgroundColor(android.graphics.Color.TRANSPARENT)
                    view.alpha = 1.0f
                    true
                }
                DragEvent.ACTION_DROP -> {
                    // Убираем подсветку
                    view.setBackgroundColor(android.graphics.Color.TRANSPARENT)
                    view.alpha = 1.0f

                    val dragData = event.clipData.getItemAt(0).text.toString()
                    if (dragData.contains("|dropzone_")) {
                        val draggedNumber = dragData.split("|")[0].toInt()
                        val sourceIndex = dragData.split("_")[1].toInt()
                        returnCardFromDropZone(draggedNumber, sourceIndex)
                    }
                    true
                }
                DragEvent.ACTION_DRAG_ENDED -> {
                    // Убираем подсветку на всякий случай
                    view.setBackgroundColor(android.graphics.Color.TRANSPARENT)
                    view.alpha = 1.0f
                    true
                }
                else -> false
            }
        }

        // Настраиваем второй ряд как drop zone
        secondRowContainer.setOnDragListener { view, event ->
            when (event.action) {
                DragEvent.ACTION_DRAG_STARTED -> true
                DragEvent.ACTION_DRAG_ENTERED -> {
                    view.setBackgroundColor(ContextCompat.getColor(this, android.R.color.holo_blue_light))
                    view.alpha = 0.3f
                    true
                }
                DragEvent.ACTION_DRAG_EXITED -> {
                    view.setBackgroundColor(android.graphics.Color.TRANSPARENT)
                    view.alpha = 1.0f
                    true
                }
                DragEvent.ACTION_DROP -> {
                    view.setBackgroundColor(android.graphics.Color.TRANSPARENT)
                    view.alpha = 1.0f

                    val dragData = event.clipData.getItemAt(0).text.toString()
                    if (dragData.contains("|dropzone_")) {
                        val draggedNumber = dragData.split("|")[0].toInt()
                        val sourceIndex = dragData.split("_")[1].toInt()
                        returnCardFromDropZone(draggedNumber, sourceIndex)
                    }
                    true
                }
                DragEvent.ACTION_DRAG_ENDED -> {
                    view.setBackgroundColor(android.graphics.Color.TRANSPARENT)
                    view.alpha = 1.0f
                    true
                }
                else -> false
            }
        }
    }

    private fun returnCardFromDropZone(number: Int, sourceIndex: Int) {
        // Очищаем исходную ячейку
        dropZones[sourceIndex].text = ""
        dropZones[sourceIndex].setBackgroundResource(R.drawable.number_drop_zone)
        userAnswers[sourceIndex] = -1

        // Добавляем карточку обратно в область выбора
        addCardBackToSelection(number)
    }

    private fun resetDropZoneBackground(dropZone: TextView, index: Int) {
        if (index == shownPosition) {
            dropZone.setBackgroundResource(R.drawable.number_input_shown)
        } else if (dropZone.text.isNotEmpty()) {
            dropZone.setBackgroundResource(R.drawable.number_drop_zone_filled)
        } else {
            dropZone.setBackgroundResource(R.drawable.number_drop_zone)
        }
    }

    private fun createDraggableCard(number: Int): TextView {
        val card = TextView(this).apply {
            text = number.toString()
            textSize = 20f
            setTextColor(ContextCompat.getColor(this@AscendingSequenceActivity, android.R.color.black))
            setBackgroundResource(R.drawable.draggable_number_card)
            gravity = android.view.Gravity.CENTER
            setPadding(24, 16, 24, 16)

            // Используем фиксированные размеры вместо app_icon_size
            val layoutParams = LinearLayout.LayoutParams(
                120, // ширина в пикселях (примерно 60dp)
                120  // высота в пикселях (примерно 60dp)
            ).apply {
                setMargins(8, 8, 8, 8)
            }
            this.layoutParams = layoutParams

            // Настройка drag functionality
            setOnTouchListener { view, event ->
                if (event.action == MotionEvent.ACTION_DOWN) {
                    val clipData = ClipData.newPlainText("number", number.toString())
                    val shadowBuilder = View.DragShadowBuilder(view)
                    view.startDragAndDrop(clipData, shadowBuilder, view, 0)
                    true
                } else {
                    false
                }
            }
        }
        return card
    }

    private fun removeDraggedCard(number: Int) {
        val firstRowContainer = findViewById<LinearLayout>(R.id.firstRowContainer)
        val secondRowContainer = findViewById<LinearLayout>(R.id.secondRowContainer)

        // Ищем карточку в первом ряду
        for (i in 0 until firstRowContainer.childCount) {
            val child = firstRowContainer.getChildAt(i) as TextView
            if (child.text.toString() == number.toString()) {
                firstRowContainer.removeView(child)
                return
            }
        }

        // Ищем карточку в�� втором ряду
        for (i in 0 until secondRowContainer.childCount) {
            val child = secondRowContainer.getChildAt(i) as TextView
            if (child.text.toString() == number.toString()) {
                secondRowContainer.removeView(child)
                return
            }
        }
    }

    private fun generateNewQuestion() {
        hasTriedCurrentQuestion = false
        checkButton.isEnabled = true
        nextButton.visibility = Button.GONE
        userAnswers.fill(-1)

        // Генерируем случайную позицию для показанного числа (0-4)
        shownPosition = Random.nextInt(sequenceSize)

        // Генерируем показанное число от 0 до 9
        shownNumber = Random.nextInt(10)

        // Вычисляем начальное число последовательности
        startNumber = shownNumber - shownPosition

        // Если начальное число меньше 0, корректируем
        if (startNumber < 0) {
            startNumber = 0
            shownNumber = shownPosition
        }

        // Если последовательность выходит за 9, корректируем
        if (startNumber + sequenceSize - 1 > 9) {
            startNumber = 9 - sequenceSize + 1
            shownNumber = startNumber + shownPosition
        }

        // Очищаем и настраиваем drop zones
        dropZones.forEachIndexed { index, dropZone ->
            if (index == shownPosition) {
                dropZone.text = shownNumber.toString()
                dropZone.setBackgroundResource(R.drawable.number_input_shown)
                userAnswers[index] = shownNumber
            } else {
                dropZone.text = ""
                dropZone.setBackgroundResource(R.drawable.number_drop_zone)
            }
        }

        // Создаем доступные числа для перетаскивания
        availableNumbers.clear()
        for (i in 0 until sequenceSize) {
            val number = startNumber + i
            if (number != shownNumber) { // Исключаем показанное число, а не позицию
                availableNumbers.add(number)
            }
        }

        // Добавляем несколько лишних чисел для усложнения
        val extraNumbers = mutableSetOf<Int>()
        while (extraNumbers.size < 3) {
            val extraNumber = Random.nextInt(10)
            if (extraNumber !in (startNumber until startNumber + sequenceSize)) {
                extraNumbers.add(extraNumber)
            }
        }
        availableNumbers.addAll(extraNumbers)

        // Перемешиваем числа
        availableNumbers.shuffle()

        // Создаем перетаскиваемые карточки и размещаем их по 4 в ряд
        val firstRowContainer = findViewById<LinearLayout>(R.id.firstRowContainer)
        val secondRowContainer = findViewById<LinearLayout>(R.id.secondRowContainer)

        firstRowContainer.removeAllViews()
        secondRowContainer.removeAllViews()

        availableNumbers.forEachIndexed { index, number ->
            val card = createDraggableCard(number)

            if (index < 4) {
                firstRowContainer.addView(card)
            } else {
                secondRowContainer.addView(card)
            }
        }

        updateProgress()
        updateQuestionText()
        speakQuestion()
    }

    private fun updateQuestionText() {
        questionText.text = getString(R.string.ascending_question)
        hintText.text = getString(R.string.ascending_hint_drag)
    }

    private fun updateProgress() {
        progressBar.progress = ((currentQuestion.toFloat() / totalQuestions) * 100).toInt()
    }

    private fun checkAnswer() {
        if (!hasTriedCurrentQuestion) {
            hasTriedCurrentQuestion = true
        }

        var allCorrect = true

        // Проверяем каждую drop zone
        dropZones.forEachIndexed { index, dropZone ->
            val correctAnswer = startNumber + index
            val userAnswer = userAnswers[index]

            if (userAnswer == correctAnswer) {
                dropZone.setBackgroundResource(R.drawable.number_input_correct)
                animateCorrectAnswer(dropZone)
            } else {
                dropZone.setBackgroundResource(R.drawable.number_input_incorrect)
                animateIncorrectAnswer(dropZone)
                allCorrect = false
            }
        }

        if (allCorrect) {
            score += 100
            totalCorrectAnswers++
            showCorrectFeedback()
            checkButton.isEnabled = false
            nextButton.visibility = Button.VISIBLE
        } else {
            showIncorrectFeedback()
        }
    }

    private fun showCorrectFeedback() {
        val phrase = correctPhrases.random()
        hintText.text = phrase
        hintText.setTextColor(ContextCompat.getColor(this, android.R.color.holo_green_dark))
        speakText(phrase)
    }

    private fun showIncorrectFeedback() {
        hintText.text = getString(R.string.ascending_incorrect_try_again)
        hintText.setTextColor(ContextCompat.getColor(this, android.R.color.holo_red_dark))
        speakText(getString(R.string.ascending_incorrect_try_again_short))
    }

    private fun nextQuestion() {
        currentQuestion++

        if (currentQuestion >= totalQuestions) {
            finishGame()
        } else {
            generateNewQuestion()
        }
    }

    private fun finishGame() {
        val intent = Intent(this, AscendingSequenceResultsActivity::class.java)
        intent.putExtra("score", score)
        intent.putExtra("totalCorrectAnswers", totalCorrectAnswers)
        intent.putExtra("totalQuestions", totalQuestions)
        startActivity(intent)
        finish()
    }

    private fun animateCorrectAnswer(view: TextView) {
        val scaleX = ObjectAnimator.ofFloat(view, "scaleX", 1f, 1.2f, 1f)
        val scaleY = ObjectAnimator.ofFloat(view, "scaleY", 1f, 1.2f, 1f)
        val animatorSet = AnimatorSet()
        animatorSet.playTogether(scaleX, scaleY)
        animatorSet.duration = 300
        animatorSet.start()
    }

    private fun animateIncorrectAnswer(view: TextView) {
        val shake = ObjectAnimator.ofFloat(view, "translationX", 0f, -10f, 10f, -5f, 5f, 0f)
        shake.duration = 500
        shake.start()
    }

    private fun speakQuestion() {
        if (tts == null) return
        val template = getString(R.string.ascending_speak_question_template)
        speakText(String.format(template, shownNumber))
    }

    private fun speakText(text: String) {
        tts?.speak(text, TextToSpeech.QUEUE_FLUSH, null, null)
    }

    override fun onInit(status: Int) {
        if (status == TextToSpeech.SUCCESS) {
            val locale = when (LocaleManager.getCurrentLanguage(this)) {
                LocaleManager.LANGUAGE_ENGLISH -> Locale.forLanguageTag("en-US")
                else -> Locale.forLanguageTag("ru-RU")
            }
            val result = tts!!.setLanguage(locale)
            if (result == TextToSpeech.LANG_MISSING_DATA || result == TextToSpeech.LANG_NOT_SUPPORTED) {
                tts!!.setLanguage(Locale.getDefault())
            }
            // Озвучиваем вопрос после успешной инициализации TTS
            speakQuestion()
        }
    }

    override fun onDestroy() {
        tts?.stop()
        tts?.shutdown()
        super.onDestroy()
    }

    private fun returnCardToSelection(dropZone: TextView, index: Int) {
        // Проверяем, что это не стартовое число и ячейка не пустая
        if (index != shownPosition && dropZone.text.isNotEmpty()) {
            val number = dropZone.text.toString().toInt()

            // Очищаем ячейку
            dropZone.text = ""
            dropZone.setBackgroundResource(R.drawable.number_drop_zone)
            userAnswers[index] = -1

            // Возвращаем карточку в блок выбора
            addCardBackToSelection(number)
        }
    }

    private fun addCardBackToSelection(number: Int) {
        val firstRowContainer = findViewById<LinearLayout>(R.id.firstRowContainer)
        val secondRowContainer = findViewById<LinearLayout>(R.id.secondRowContainer)

        // Создаем новую карточку
        val card = createDraggableCard(number)

        // Добавляем в первый ряд, если там меньше 4 карточек, иначе во второй
        if (firstRowContainer.childCount < 4) {
            firstRowContainer.addView(card)
        } else {
            secondRowContainer.addView(card)
        }
    }

    private fun handleCardDrop(dropZone: TextView, index: Int, draggedNumber: Int, sourceType: String) {
        // Если это защищенная ячейка с показанным числом, не позволяем ничего делать
        if (index == shownPosition) {
            return
        }

        // Если карточка перетаскивается из области выбора
        if (sourceType == "selection") {
            // Если ячейка уже занята, возвращаем предыдущую карточку в область выбора
            if (dropZone.text.isNotEmpty()) {
                val previousNumber = dropZone.text.toString().toInt()
                addCardBackToSelection(previousNumber)
            }

            // Размещаем новую карточку
            dropZone.text = draggedNumber.toString()
            dropZone.setBackgroundResource(R.drawable.number_drop_zone_filled)
            userAnswers[index] = draggedNumber

            // Удаляем использованную карточку из области выбора
            removeDraggedCard(draggedNumber)
        }
        // Если карточка перетаскивается из другой ячейки
        else if (sourceType.startsWith("dropzone_")) {
            val sourceIndex = sourceType.split("_")[1].toInt()

            // Если ячейка назначения пустая - просто перемещаем
            if (dropZone.text.isEmpty()) {
                dropZone.text = draggedNumber.toString()
                dropZone.setBackgroundResource(R.drawable.number_drop_zone_filled)
                userAnswers[index] = draggedNumber

                // Очищаем исходную ячейку
                dropZones[sourceIndex].text = ""
                dropZones[sourceIndex].setBackgroundResource(R.drawable.number_drop_zone)
                userAnswers[sourceIndex] = -1
            }
            // Если ячейка назначения занята - меняем карточки местами
            else {
                val targetNumber = dropZone.text.toString().toInt()

                // Выполняем обмен карточками
                dropZone.text = draggedNumber.toString()
                dropZones[sourceIndex].text = targetNumber.toString()

                // Обновляем массив ответов
                userAnswers[index] = draggedNumber
                userAnswers[sourceIndex] = targetNumber

                // Обновляем фоны
                dropZone.setBackgroundResource(R.drawable.number_drop_zone_filled)
                dropZones[sourceIndex].setBackgroundResource(R.drawable.number_drop_zone_filled)
            }
        }
    }
}

package com.timursarsembayev.danabalanumbers

import android.content.Intent
import android.os.Bundle
import android.speech.tts.TextToSpeech
import android.widget.Button
import android.widget.ProgressBar
import android.widget.TextView
import androidx.appcompat.app.AppCompatActivity
import androidx.core.view.ViewCompat
import androidx.core.view.WindowInsetsCompat
import java.util.*

class AscendingSequenceResultsActivity : AppCompatActivity(), TextToSpeech.OnInitListener {

    private var tts: TextToSpeech? = null

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_ascending_sequence_results)

        ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main)) { v, insets ->
            val systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars())
            v.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom)
            insets
        }

        tts = TextToSpeech(this, this)

        val score = intent.getIntExtra("score", 0)
        val totalCorrectAnswers = intent.getIntExtra("totalCorrectAnswers", 0)
        val totalQuestions = intent.getIntExtra("totalQuestions", 20)

        displayResults(score, totalCorrectAnswers, totalQuestions)
        setupButtons()
    }

    private fun displayResults(score: Int, correctAnswers: Int, totalQuestions: Int) {
        val scoreText = findViewById<TextView>(R.id.scoreText)
        val accuracyText = findViewById<TextView>(R.id.accuracyText)
        val progressBar = findViewById<ProgressBar>(R.id.accuracyProgressBar)
        val congratsText = findViewById<TextView>(R.id.congratsText)

        scoreText.text = "Очки: $score"

        val accuracy = (correctAnswers.toFloat() / totalQuestions * 100).toInt()
        accuracyText.text = "Правильных ответов: $correctAnswers из $totalQuestions ($accuracy%)"
        progressBar.progress = accuracy

        val message = when {
            accuracy >= 90 -> {
                congratsText.text = " Превосходно! "
                "Отличная работа! Ты великолепно справился с упражнением по возрастанию!"
            }
            accuracy >= 70 -> {
                congratsText.text = " Хорошо! "
                "Хорошая работа! Продолжай тренироваться!"
            }
            accuracy >= 50 -> {
                congratsText.text = " Неплохо! "
                "Неплохой результат! Попробуй еще раз!"
            }
            else -> {
                congratsText.text = " Попробуй еще! "
                "Не расстраивайся! Попробуй еще раз, и у тебя обязательно получится!"
            }
        }

        speakText(message)
    }

    private fun setupButtons() {
        findViewById<Button>(R.id.playAgainButton).setOnClickListener {
            val intent = Intent(this, AscendingSequenceActivity::class.java)
            startActivity(intent)
            finish()
        }

        findViewById<Button>(R.id.backToMenuButton).setOnClickListener {
            val intent = Intent(this, MathExercisesActivity::class.java)
            startActivity(intent)
            finish()
        }
    }

    private fun speakText(text: String) {
        tts?.speak(text, TextToSpeech.QUEUE_FLUSH, null, null)
    }

    override fun onInit(status: Int) {
        if (status == TextToSpeech.SUCCESS) {
            val result = tts!!.setLanguage(Locale("ru", "RU"))
            if (result == TextToSpeech.LANG_MISSING_DATA || result == TextToSpeech.LANG_NOT_SUPPORTED) {
                tts!!.setLanguage(Locale.getDefault())
            }
        }
    }

    override fun onDestroy() {
        tts?.stop()
        tts?.shutdown()
        super.onDestroy()
    }
}

package com.timursarsembayev.danabalanumbers

import android.content.Context
import android.content.Intent
import android.os.Bundle
import android.speech.tts.TextToSpeech
import android.widget.Button
import android.widget.ProgressBar
import android.widget.TextView
import androidx.appcompat.app.AppCompatActivity
import androidx.core.view.ViewCompat
import androidx.core.view.WindowInsetsCompat
import java.util.*

class AscendingSequenceResultsActivity : AppCompatActivity(), TextToSpeech.OnInitListener {

    private var tts: TextToSpeech? = null

    override fun attachBaseContext(newBase: Context) {
        super.attachBaseContext(LocaleManager.applyLanguage(newBase))
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_ascending_sequence_results)

        ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main)) { v, insets ->
            val systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars())
            v.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom)
            insets
        }

        // Инициализируем TTS только для ru/en; для kk — отключаем
        when (LocaleManager.getCurrentLanguage(this)) {
            LocaleManager.LANGUAGE_ENGLISH, LocaleManager.LANGUAGE_RUSSIAN -> {
                tts = TextToSpeech(this, this)
            }
            else -> tts = null
        }

        val score = intent.getIntExtra("score", 0)
        val totalCorrectAnswers = intent.getIntExtra("totalCorrectAnswers", 0)
        val totalQuestions = intent.getIntExtra("totalQuestions", 20)

        displayResults(score, totalCorrectAnswers, totalQuestions)
        setupButtons()
    }

    private fun displayResults(score: Int, correctAnswers: Int, totalQuestions: Int) {
        val scoreText = findViewById<TextView>(R.id.scoreText)
        val accuracyText = findViewById<TextView>(R.id.accuracyText)
        val progressBar = findViewById<ProgressBar>(R.id.accuracyProgressBar)
        val congratsText = findViewById<TextView>(R.id.congratsText)

        scoreText.text = getString(R.string.ascending_score_points, score)

        val accuracy = (correctAnswers.toFloat() / totalQuestions * 100).toInt()
        accuracyText.text = getString(R.string.ascending_results_accuracy_line, correctAnswers, totalQuestions, accuracy)
        progressBar.progress = accuracy

        val message = when {
            accuracy >= 90 -> {
                congratsText.text = getString(R.string.ascending_results_congrats_excellent)
                getString(R.string.ascending_results_message_excellent)
            }
            accuracy >= 70 -> {
                congratsText.text = getString(R.string.ascending_results_congrats_good)
                getString(R.string.ascending_results_message_good)
            }
            accuracy >= 50 -> {
                congratsText.text = getString(R.string.ascending_results_congrats_ok)
                getString(R.string.ascending_results_message_ok)
            }
            else -> {
                congratsText.text = getString(R.string.ascending_results_congrats_try)
                getString(R.string.ascending_results_message_try)
            }
        }

        speakText(message)
    }

    private fun setupButtons() {
        findViewById<Button>(R.id.playAgainButton).setOnClickListener {
            val intent = Intent(this, AscendingSequenceActivity::class.java)
            startActivity(intent)
            finish()
        }

        findViewById<Button>(R.id.backToMenuButton).setOnClickListener {
            val intent = Intent(this, MathExercisesActivity::class.java)
            startActivity(intent)
            finish()
        }
    }

    private fun speakText(text: String) {
        tts?.speak(text, TextToSpeech.QUEUE_FLUSH, null, null)
    }

    override fun onInit(status: Int) {
        if (status == TextToSpeech.SUCCESS) {
            val locale = when (LocaleManager.getCurrentLanguage(this)) {
                LocaleManager.LANGUAGE_ENGLISH -> Locale.forLanguageTag("en-US")
                else -> Locale.forLanguageTag("ru-RU")
            }
            val result = tts!!.setLanguage(locale)
            if (result == TextToSpeech.LANG_MISSING_DATA || result == TextToSpeech.LANG_NOT_SUPPORTED) {
                tts!!.setLanguage(Locale.getDefault())
            }
        }
    }

    override fun onDestroy() {
        tts?.stop()
        tts?.shutdown()
        super.onDestroy()
    }
}

package com.timursarsembayev.danabalanumbers

import android.animation.Animator
import android.animation.AnimatorListenerAdapter
import android.animation.ValueAnimator
import android.content.Intent
import android.os.Bundle
import android.speech.tts.TextToSpeech
import android.view.View
import android.widget.ImageView
import android.widget.LinearLayout
import android.widget.ProgressBar
import android.widget.TextView
import androidx.appcompat.app.AppCompatActivity
import androidx.recyclerview.widget.LinearLayoutManager
import androidx.recyclerview.widget.RecyclerView
import java.util.Locale
import kotlin.random.Random

class AudioMatchingActivity : AppCompatActivity(), TextToSpeech.OnInitListener {

    private lateinit var audioButtonsRecyclerView: RecyclerView
    private lateinit var numbersRecyclerView: RecyclerView
    private lateinit var audioButtonsAdapter: AudioButtonsAdapter
    private lateinit var numbersAdapter: NumbersAdapter
    private lateinit var progressBar: ProgressBar
    private lateinit var backButton: ImageView

    private var currentLevel = 1
    private var totalLevels = 10
    private var levels = mutableListOf<AudioMatchingLevel>()
    private var currentLevelData: AudioMatchingLevel? = null

    private var selectedAudioItem: MatchingItem? = null
    private var selectedNumberItem: MatchingItem? = null
    private var selectedAudioView: View? = null
    private var selectedNumberView: View? = null

    private var completedMatches = 0
    private var correctActions = 0
    private var incorrectActions = 0

    private lateinit var tts: TextToSpeech
    private var isTtsReady = false

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_audio_matching)

        initTTS()
        initViews()
        initData()
        setupRecyclerViews()
        loadLevel(currentLevel)
    }

    private fun initTTS() {
        tts = TextToSpeech(this, this)
    }

    override fun onInit(status: Int) {
        if (status == TextToSpeech.SUCCESS) {
            val result = tts.setLanguage(Locale("ru"))
            isTtsReady = result != TextToSpeech.LANG_MISSING_DATA && result != TextToSpeech.LANG_NOT_SUPPORTED
        }
    }

    private fun speakNumber(number: Int) {
        if (isTtsReady) {
            val numberText = when (number) {
                1 -> "один"
                2 -> "два"
                3 -> "три"
                4 -> "четыре"
                5 -> "пять"
                6 -> "шесть"
                7 -> "семь"
                8 -> "восемь"
                9 -> "девять"
                else -> number.toString()
            }
            tts.speak(numberText, TextToSpeech.QUEUE_FLUSH, null, null)
        }
    }

    private fun speakText(text: String) {
        if (isTtsReady) {
            tts.speak(text, TextToSpeech.QUEUE_FLUSH, null, null)
        }
    }

    private fun initViews() {
        audioButtonsRecyclerView = findViewById(R.id.audioButtonsRecyclerView)
        numbersRecyclerView = findViewById(R.id.numbersRecyclerView)
        progressBar = findViewById(R.id.progressBar)
        backButton = findViewById(R.id.backButton)

        backButton.setOnClickListener {
            finish()
        }
    }

    private fun initData() {
        levels = AudioMatchingGameData.generateAllLevels().toMutableList()
    }

    private fun setupRecyclerViews() {
        audioButtonsAdapter = AudioButtonsAdapter(mutableListOf()) { item, view ->
            onAudioButtonClick(item, view)
        }

        numbersAdapter = NumbersAdapter(mutableListOf()) { item, view ->
            onNumberItemClick(item, view)
        }

        audioButtonsRecyclerView.apply {
            layoutManager = LinearLayoutManager(this@AudioMatchingActivity)
            adapter = audioButtonsAdapter
        }

        numbersRecyclerView.apply {
            layoutManager = LinearLayoutManager(this@AudioMatchingActivity)
            adapter = numbersAdapter
        }
    }

    private fun loadLevel(level: Int) {
        currentLevelData = levels[level - 1]
        updateProgressBar()
        completedMatches = 0

        // Перемешиваем элементы для случайного порядка
        val audioButtons = currentLevelData!!.pairs.map { it.number }.shuffled()
        val numbers = currentLevelData!!.pairs.map { it.number }.shuffled()

        audioButtonsAdapter.updateItems(audioButtons)
        numbersAdapter.updateItems(numbers)

        clearSelections()
        resetViewsAlpha()
    }

    private fun updateProgressBar() {
        val progress = (currentLevel * 100) / totalLevels
        progressBar.progress = progress
    }

    private fun resetViewsAlpha() {
        audioButtonsRecyclerView.post {
            for (i in 0 until audioButtonsRecyclerView.childCount) {
                val child = audioButtonsRecyclerView.getChildAt(i)
                child.alpha = 1.0f
                child.scaleX = 1.0f
                child.scaleY = 1.0f
            }
        }

        numbersRecyclerView.post {
            for (i in 0 until numbersRecyclerView.childCount) {
                val child = numbersRecyclerView.getChildAt(i)
                child.alpha = 1.0f
                child.scaleX = 1.0f
                child.scaleY = 1.0f
            }
        }
    }

    private fun onAudioButtonClick(item: MatchingItem, view: View) {
        if (item.isMatched) return

        // Озвучиваем число
        speakNumber(item.value)

        // Убираем предыдущее выделение
        selectedAudioView?.let { prevView ->
            val linearLayout = prevView.findViewById<LinearLayout>(R.id.audioButtonLayout)
            linearLayout?.setBackgroundColor(androidx.core.content.ContextCompat.getColor(this, android.R.color.white))
        }

        if (selectedAudioItem == item) {
            clearSelections()
            return
        }

        selectedAudioItem = item
        selectedAudioView = view

        // Выделяем элемент зеленым цветом
        val linearLayout = view.findViewById<LinearLayout>(R.id.audioButtonLayout)
        linearLayout?.setBackgroundColor(androidx.core.content.ContextCompat.getColor(this, android.R.color.holo_green_light))

        checkMatch()
    }

    private fun onNumberItemClick(item: MatchingItem, view: View) {
        if (item.isMatched) return

        // Убираем предыдущее выделение
        selectedNumberView?.let { prevView ->
            val numberText = prevView.findViewById<TextView>(R.id.numberText)
            numberText?.setBackgroundColor(androidx.core.content.ContextCompat.getColor(this, R.color.button_color))
        }

        if (selectedNumberItem == item) {
            clearSelections()
            return
        }

        selectedNumberItem = item
        selectedNumberView = view

        // Выделяем элемент зеленым цветом
        val numberText = view.findViewById<TextView>(R.id.numberText)
        numberText?.setBackgroundColor(androidx.core.content.ContextCompat.getColor(this, android.R.color.holo_green_light))

        checkMatch()
    }

    private fun checkMatch() {
        val audioItem = selectedAudioItem
        val numberItem = selectedNumberItem

        if (audioItem != null && numberItem != null) {
            if (audioItem.value == numberItem.value) {
                onCorrectMatch(audioItem, numberItem)
            } else {
                onIncorrectMatch()
            }
        }
    }

    private fun onCorrectMatch(audioItem: MatchingItem, numberItem: MatchingItem) {
        correctActions++

        val randomPhrase = MatchingFeedbackPhrases.correctPhrases[Random.nextInt(MatchingFeedbackPhrases.correctPhrases.size)]
        speakText(randomPhrase)

        audioItem.isMatched = true
        numberItem.isMatched = true

        animateMatch(selectedAudioView!!, selectedNumberView!!) {
            audioButtonsAdapter.removeItem(audioItem)
            numbersAdapter.removeItem(numberItem)

            completedMatches++

            if (completedMatches >= 5) {
                onLevelCompleted()
            }
        }

        clearSelections()
    }

    private fun onIncorrectMatch() {
        incorrectActions++

        val randomPhrase = MatchingFeedbackPhrases.incorrectPhrases[Random.nextInt(MatchingFeedbackPhrases.incorrectPhrases.size)]
        speakText(randomPhrase)

        // Выделяем обе карточки красным цветом на полсекунды
        selectedAudioView?.let { view ->
            val linearLayout = view.findViewById<LinearLayout>(R.id.audioButtonLayout)
            linearLayout?.setBackgroundColor(androidx.core.content.ContextCompat.getColor(this, android.R.color.holo_red_light))
        }

        selectedNumberView?.let { view ->
            val numberText = view.findViewById<TextView>(R.id.numberText)
            numberText?.setBackgroundColor(androidx.core.content.ContextCompat.getColor(this, android.R.color.holo_red_light))
        }

        // Через 500ms возвращаем зеленое выделение
        android.os.Handler(android.os.Looper.getMainLooper()).postDelayed({
            selectedAudioView?.let { view ->
                val linearLayout = view.findViewById<LinearLayout>(R.id.audioButtonLayout)
                linearLayout?.setBackgroundColor(androidx.core.content.ContextCompat.getColor(this, android.R.color.holo_green_light))
            }

            selectedNumberView?.let { view ->
                val numberText = view.findViewById<TextView>(R.id.numberText)
                numberText?.setBackgroundColor(androidx.core.content.ContextCompat.getColor(this, android.R.color.holo_green_light))
            }
        }, 500)

        animateIncorrectMatch(selectedAudioView!!, selectedNumberView!!)
    }

    private fun animateMatch(view1: View, view2: View, onComplete: () -> Unit) {
        val animator1 = ValueAnimator.ofFloat(1f, 0f)
        val animator2 = ValueAnimator.ofFloat(1f, 0f)

        animator1.duration = 300
        animator2.duration = 300

        animator1.addUpdateListener { animation ->
            val alpha = animation.animatedValue as Float
            view1.alpha = alpha
            view1.scaleX = alpha
            view1.scaleY = alpha
        }

        animator2.addUpdateListener { animation ->
            val alpha = animation.animatedValue as Float
            view2.alpha = alpha
            view2.scaleX = alpha
            view2.scaleY = alpha
        }

        animator1.addListener(object : AnimatorListenerAdapter() {
            override fun onAnimationEnd(animation: Animator) {
                onComplete()
            }
        })

        animator1.start()
        animator2.start()
    }

    private fun animateIncorrectMatch(view1: View, view2: View) {
        val shake = ValueAnimator.ofFloat(0f, 25f, -25f, 25f, -25f, 15f, -15f, 6f, -6f, 0f)
        shake.duration = 600

        shake.addUpdateListener { animation ->
            val translateX = animation.animatedValue as Float
            view1.translationX = translateX
            view2.translationX = translateX
        }

        shake.addListener(object : AnimatorListenerAdapter() {
            override fun onAnimationEnd(animation: Animator) {
                view1.translationX = 0f
                view2.translationX = 0f
            }
        })

        shake.start()
    }

    private fun clearSelections() {
        selectedAudioItem = null
        selectedNumberItem = null

        selectedAudioView?.let { view ->
            val linearLayout = view.findViewById<LinearLayout>(R.id.audioButtonLayout)
            linearLayout?.setBackgroundColor(androidx.core.content.ContextCompat.getColor(this, android.R.color.white))
        }

        selectedNumberView?.let { view ->
            val numberText = view.findViewById<TextView>(R.id.numberText)
            numberText?.setBackgroundColor(androidx.core.content.ContextCompat.getColor(this, R.color.button_color))
        }

        selectedAudioView = null
        selectedNumberView = null
    }

    private fun onLevelCompleted() {
        if (currentLevel < totalLevels) {
            currentLevel++
            loadLevel(currentLevel)
        } else {
            showResults()
        }
    }

    private fun showResults() {
        val finalScore = (correctActions * 10) - (incorrectActions * 5)

        val intent = Intent(this, AudioMatchingResultsActivity::class.java)
        intent.putExtra("completed_levels", currentLevel)
        intent.putExtra("correct_actions", correctActions)
        intent.putExtra("incorrect_actions", incorrectActions)
        intent.putExtra("final_score", finalScore)
        startActivity(intent)
        finish()
    }

    override fun onDestroy() {
        if (::tts.isInitialized) {
            tts.stop()
            tts.shutdown()
        }
        super.onDestroy()
    }
}

package com.timursarsembayev.danabalanumbers

import android.animation.Animator
import android.animation.AnimatorListenerAdapter
import android.animation.ValueAnimator
import android.content.Context
import android.content.Intent
import android.os.Bundle
import android.speech.tts.TextToSpeech
import android.view.View
import android.widget.ImageView
import android.widget.LinearLayout
import android.widget.ProgressBar
import android.widget.TextView
import androidx.appcompat.app.AppCompatActivity
import androidx.recyclerview.widget.LinearLayoutManager
import androidx.recyclerview.widget.RecyclerView
import java.util.Locale
import kotlin.random.Random

class AudioMatchingActivity : AppCompatActivity(), TextToSpeech.OnInitListener {

    private lateinit var audioButtonsRecyclerView: RecyclerView
    private lateinit var numbersRecyclerView: RecyclerView
    private lateinit var audioButtonsAdapter: AudioButtonsAdapter
    private lateinit var numbersAdapter: NumbersAdapter
    private lateinit var progressBar: ProgressBar
    private lateinit var backButton: ImageView

    private var currentLevel = 1
    private var totalLevels = 10
    private var levels = mutableListOf<AudioMatchingLevel>()
    private var currentLevelData: AudioMatchingLevel? = null

    private var selectedAudioItem: MatchingItem? = null
    private var selectedNumberItem: MatchingItem? = null
    private var selectedAudioView: View? = null
    private var selectedNumberView: View? = null

    private var completedMatches = 0
    private var correctActions = 0
    private var incorrectActions = 0

    private var allowTts = true
    private var isTtsReady = false
    private var tts: TextToSpeech? = null

    private lateinit var correctPhrases: Array<String>
    private lateinit var incorrectPhrases: Array<String>

    override fun attachBaseContext(newBase: Context?) {
        super.attachBaseContext(newBase?.let { LocaleManager.applyLanguage(it) })
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_audio_matching)

        // Определяем текущий язык и отключаем TTS для казахского
        val currentLang = LocaleManager.getCurrentLanguage(this).lowercase(Locale.ROOT)
        allowTts = currentLang != LocaleManager.LANGUAGE_KAZAKH

        initTTS()
        initViews()
        initData()
        setupRecyclerViews()

        // Локализованные фразы поощрения/поддержки
        correctPhrases = resources.getStringArray(R.array.matching_correct_phrases)
        incorrectPhrases = resources.getStringArray(R.array.matching_incorrect_phrases)

        loadLevel(currentLevel)
    }

    private fun initTTS() {
        if (allowTts) {
            tts = TextToSpeech(this, this)
        }
    }

    override fun onInit(status: Int) {
        if (!allowTts) return
        if (status == TextToSpeech.SUCCESS) {
            val langCode = LocaleManager.getCurrentLanguage(this)
            val locale = when (langCode) {
                LocaleManager.LANGUAGE_RUSSIAN -> Locale.forLanguageTag("ru-RU")
                LocaleManager.LANGUAGE_ENGLISH -> Locale.forLanguageTag("en-US")
                else -> Locale.forLanguageTag("en-US")
            }
            val result = tts?.setLanguage(locale)
            isTtsReady = result != TextToSpeech.LANG_MISSING_DATA && result != TextToSpeech.LANG_NOT_SUPPORTED
        }
    }

    private fun speakNumber(number: Int) {
        if (!allowTts || !isTtsReady) return
        // Берем названия чисел из ресурсов (локализовано)
        val names = resources.getStringArray(R.array.number_names_1_9)
        val spoken = if (number in 1..9) names[number - 1] else number.toString()
        tts?.speak(spoken, TextToSpeech.QUEUE_FLUSH, null, "audio_number")
    }

    private fun speakText(text: String) {
        if (allowTts && isTtsReady) {
            tts?.speak(text, TextToSpeech.QUEUE_FLUSH, null, "audio_phrase")
        }
    }

    private fun initViews() {
        audioButtonsRecyclerView = findViewById(R.id.audioButtonsRecyclerView)
        numbersRecyclerView = findViewById(R.id.numbersRecyclerView)
        progressBar = findViewById(R.id.progressBar)
        backButton = findViewById(R.id.backButton)

        backButton.setOnClickListener {
            finish()
        }
    }

    private fun initData() {
        levels = AudioMatchingGameData.generateAllLevels().toMutableList()
    }

    private fun setupRecyclerViews() {
        audioButtonsAdapter = AudioButtonsAdapter(mutableListOf()) { item, view ->
            onAudioButtonClick(item, view)
        }

        numbersAdapter = NumbersAdapter(mutableListOf()) { item, view ->
            onNumberItemClick(item, view)
        }

        audioButtonsRecyclerView.apply {
            layoutManager = LinearLayoutManager(this@AudioMatchingActivity)
            adapter = audioButtonsAdapter
        }

        numbersRecyclerView.apply {
            layoutManager = LinearLayoutManager(this@AudioMatchingActivity)
            adapter = numbersAdapter
        }
    }

    private fun loadLevel(level: Int) {
        currentLevelData = levels[level - 1]
        updateProgressBar()
        completedMatches = 0

        // Перемешиваем элементы для случайного порядка
        val audioButtons = currentLevelData!!.pairs.map { it.number }.shuffled()
        val numbers = currentLevelData!!.pairs.map { it.number }.shuffled()

        audioButtonsAdapter.updateItems(audioButtons)
        numbersAdapter.updateItems(numbers)

        clearSelections()
        resetViewsAlpha()
    }

    private fun updateProgressBar() {
        val progress = (currentLevel * 100) / totalLevels
        progressBar.progress = progress
    }

    private fun resetViewsAlpha() {
        audioButtonsRecyclerView.post {
            for (i in 0 until audioButtonsRecyclerView.childCount) {
                val child = audioButtonsRecyclerView.getChildAt(i)
                child.alpha = 1.0f
                child.scaleX = 1.0f
                child.scaleY = 1.0f
            }
        }

        numbersRecyclerView.post {
            for (i in 0 until numbersRecyclerView.childCount) {
                val child = numbersRecyclerView.getChildAt(i)
                child.alpha = 1.0f
                child.scaleX = 1.0f
                child.scaleY = 1.0f
            }
        }
    }

    private fun onAudioButtonClick(item: MatchingItem, view: View) {
        if (item.isMatched) return

        // Озвучиваем число
        speakNumber(item.value)

        // Убираем предыдущее выделение
        selectedAudioView?.let { prevView ->
            val linearLayout = prevView.findViewById<LinearLayout>(R.id.audioButtonLayout)
            linearLayout?.setBackgroundColor(androidx.core.content.ContextCompat.getColor(this, android.R.color.white))
        }

        if (selectedAudioItem == item) {
            clearSelections()
            return
        }

        selectedAudioItem = item
        selectedAudioView = view

        // Выделяем элемент зеленым цветом
        val linearLayout = view.findViewById<LinearLayout>(R.id.audioButtonLayout)
        linearLayout?.setBackgroundColor(androidx.core.content.ContextCompat.getColor(this, android.R.color.holo_green_light))

        checkMatch()
    }

    private fun onNumberItemClick(item: MatchingItem, view: View) {
        if (item.isMatched) return

        // Убираем предыдущее выделение
        selectedNumberView?.let { prevView ->
            val numberText = prevView.findViewById<TextView>(R.id.numberText)
            numberText?.setBackgroundColor(androidx.core.content.ContextCompat.getColor(this, R.color.button_color))
        }

        if (selectedNumberItem == item) {
            clearSelections()
            return
        }

        selectedNumberItem = item
        selectedNumberView = view

        // Выделяем элемент зеленым цветом
        val numberText = view.findViewById<TextView>(R.id.numberText)
        numberText?.setBackgroundColor(androidx.core.content.ContextCompat.getColor(this, android.R.color.holo_green_light))

        checkMatch()
    }

    private fun checkMatch() {
        val audioItem = selectedAudioItem
        val numberItem = selectedNumberItem

        if (audioItem != null && numberItem != null) {
            if (audioItem.value == numberItem.value) {
                onCorrectMatch(audioItem, numberItem)
            } else {
                onIncorrectMatch()
            }
        }
    }

    private fun onCorrectMatch(audioItem: MatchingItem, numberItem: MatchingItem) {
        correctActions++

        // Озвучиваем поощрение (локализовано)
        val randomPhrase = correctPhrases[Random.nextInt(correctPhrases.size)]
        speakText(randomPhrase)

        audioItem.isMatched = true
        numberItem.isMatched = true

        animateMatch(selectedAudioView!!, selectedNumberView!!) {
            audioButtonsAdapter.removeItem(audioItem)
            numbersAdapter.removeItem(numberItem)

            completedMatches++

            if (completedMatches >= 5) {
                onLevelCompleted()
            }
        }

        clearSelections()
    }

    private fun onIncorrectMatch() {
        incorrectActions++

        // Озвучиваем подбадривание (локализовано)
        val randomPhrase = incorrectPhrases[Random.nextInt(incorrectPhrases.size)]
        speakText(randomPhrase)

        // Выделяем обе карточки красным цветом на полсекунды
        selectedAudioView?.let { view ->
            val linearLayout = view.findViewById<LinearLayout>(R.id.audioButtonLayout)
            linearLayout?.setBackgroundColor(androidx.core.content.ContextCompat.getColor(this, android.R.color.holo_red_light))
        }

        selectedNumberView?.let { view ->
            val numberText = view.findViewById<TextView>(R.id.numberText)
            numberText?.setBackgroundColor(androidx.core.content.ContextCompat.getColor(this, android.R.color.holo_red_light))
        }

        // Через 500ms возвращаем зеленое выделение
        android.os.Handler(android.os.Looper.getMainLooper()).postDelayed({
            selectedAudioView?.let { view ->
                val linearLayout = view.findViewById<LinearLayout>(R.id.audioButtonLayout)
                linearLayout?.setBackgroundColor(androidx.core.content.ContextCompat.getColor(this, android.R.color.holo_green_light))
            }

            selectedNumberView?.let { view ->
                val numberText = view.findViewById<TextView>(R.id.numberText)
                numberText?.setBackgroundColor(androidx.core.content.ContextCompat.getColor(this, android.R.color.holo_green_light))
            }
        }, 500)

        animateIncorrectMatch(selectedAudioView!!, selectedNumberView!!)
    }

    private fun animateMatch(view1: View, view2: View, onComplete: () -> Unit) {
        val animator1 = ValueAnimator.ofFloat(1f, 0f)
        val animator2 = ValueAnimator.ofFloat(1f, 0f)

        animator1.duration = 300
        animator2.duration = 300

        animator1.addUpdateListener { animation ->
            val alpha = animation.animatedValue as Float
            view1.alpha = alpha
            view1.scaleX = alpha
            view1.scaleY = alpha
        }

        animator2.addUpdateListener { animation ->
            val alpha = animation.animatedValue as Float
            view2.alpha = alpha
            view2.scaleX = alpha
            view2.scaleY = alpha
        }

        animator1.addListener(object : AnimatorListenerAdapter() {
            override fun onAnimationEnd(animation: Animator) {
                onComplete()
            }
        })

        animator1.start()
        animator2.start()
    }

    private fun animateIncorrectMatch(view1: View, view2: View) {
        val shake = ValueAnimator.ofFloat(0f, 25f, -25f, 25f, -25f, 15f, -15f, 6f, -6f, 0f)
        shake.duration = 600

        shake.addUpdateListener { animation ->
            val translateX = animation.animatedValue as Float
            view1.translationX = translateX
            view2.translationX = translateX
        }

        shake.addListener(object : AnimatorListenerAdapter() {
            override fun onAnimationEnd(animation: Animator) {
                view1.translationX = 0f
                view2.translationX = 0f
            }
        })

        shake.start()
    }

    private fun clearSelections() {
        selectedAudioItem = null
        selectedNumberItem = null

        selectedAudioView?.let { view ->
            val linearLayout = view.findViewById<LinearLayout>(R.id.audioButtonLayout)
            linearLayout?.setBackgroundColor(androidx.core.content.ContextCompat.getColor(this, android.R.color.white))
        }

        selectedNumberView?.let { view ->
            val numberText = view.findViewById<TextView>(R.id.numberText)
            numberText?.setBackgroundColor(androidx.core.content.ContextCompat.getColor(this, R.color.button_color))
        }

        selectedAudioView = null
        selectedNumberView = null
    }

    private fun onLevelCompleted() {
        if (currentLevel < totalLevels) {
            currentLevel++
            loadLevel(currentLevel)
        } else {
            showResults()
        }
    }

    private fun showResults() {
        val finalScore = (correctActions * 10) - (incorrectActions * 5)

        val intent = Intent(this, AudioMatchingResultsActivity::class.java)
        intent.putExtra("completed_levels", currentLevel)
        intent.putExtra("correct_actions", correctActions)
        intent.putExtra("incorrect_actions", incorrectActions)
        intent.putExtra("final_score", finalScore)
        startActivity(intent)
        finish()
    }

    override fun onDestroy() {
        if (allowTts) {
            tts?.stop()
            tts?.shutdown()
        }
        super.onDestroy()
    }
}

package com.timursarsembayev.danabalanumbers

import android.content.Intent
import android.os.Bundle
import android.speech.tts.TextToSpeech
import android.widget.ImageView
import android.widget.TextView
import androidx.appcompat.app.AppCompatActivity
import androidx.cardview.widget.CardView
import androidx.core.view.ViewCompat
import androidx.core.view.WindowInsetsCompat
import java.util.*
import kotlin.random.Random

class AudioMatchingResultsActivity : AppCompatActivity(), TextToSpeech.OnInitListener {

    private var tts: TextToSpeech? = null
    private var isTtsReady = false

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_audio_matching_results)

        ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main)) { v, insets ->
            val systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars())
            v.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom)
            insets
        }

        // Инициализация TTS
        tts = TextToSpeech(this, this)

        setupViews()
        setupButtons()
    }

    override fun onInit(status: Int) {
        if (status == TextToSpeech.SUCCESS) {
            val result = tts?.setLanguage(Locale("ru"))
            isTtsReady = result != TextToSpeech.LANG_MISSING_DATA && result != TextToSpeech.LANG_NOT_SUPPORTED

            if (isTtsReady) {
                speakCongratulation()
            }
        }
    }

    private fun setupViews() {
        val completedLevels = intent.getIntExtra("completed_levels", 10)
        val correctActions = intent.getIntExtra("correct_actions", 0)
        val incorrectActions = intent.getIntExtra("incorrect_actions", 0)
        val finalScore = intent.getIntExtra("final_score", 0)

        // Обновляем UI с результатами
        findViewById<TextView>(R.id.completedLevelsText).text = "Пройдено уровней: $completedLevels"
        findViewById<TextView>(R.id.correctActionsText).text = "Правильных действий: $correctActions"
        findViewById<TextView>(R.id.incorrectActionsText).text = "Ошибок: $incorrectActions"
        findViewById<TextView>(R.id.finalScoreText).text = "Итоговые очки: $finalScore"

        // Определяем сообщение в зависимости от результата
        val accuracy = if (correctActions + incorrectActions > 0) {
            (correctActions * 100) / (correctActions + incorrectActions)
        } else {
            100
        }

        val (message, encouragement) = when {
            accuracy >= 90 -> Pair("Превосходно! ", "Ты отлично слышишь и различаешь числа!")
            accuracy >= 70 -> Pair("Отлично! ", "Ты хорошо сопоставляешь звуки с цифрами!")
            accuracy >= 50 -> Pair("Хорошо! ", "Продолжай тренироваться!")
            else -> Pair("Не сдавайся! ", "С каждым разом будет лучше!")
        }

        findViewById<TextView>(R.id.resultMessage).text = message
        findViewById<TextView>(R.id.encouragementText).text = encouragement
    }

    private fun speakCongratulation() {
        if (isTtsReady) {
            val correctActions = intent.getIntExtra("correct_actions", 0)
            val incorrectActions = intent.getIntExtra("incorrect_actions", 0)

            val accuracy = if (correctActions + incorrectActions > 0) {
                (correctActions * 100) / (correctActions + incorrectActions)
            } else {
                100
            }

            val phrases = when {
                accuracy == 100 -> DifferentiatedCongratulationPhrases.perfect100Phrases
                accuracy >= 90 -> DifferentiatedCongratulationPhrases.excellent90Phrases
                accuracy >= 80 -> DifferentiatedCongratulationPhrases.good80Phrases
                else -> DifferentiatedCongratulationPhrases.encouragement80Phrases
            }

            val randomPhrase = phrases[Random.nextInt(phrases.size)]
            tts?.speak(randomPhrase, TextToSpeech.QUEUE_FLUSH, null, "congratulation")
        }
    }

    private fun setupButtons() {
        findViewById<CardView>(R.id.btnPlayAgain).setOnClickListener {
            stopTTS()
            val intent = Intent(this, AudioMatchingActivity::class.java)
            startActivity(intent)
            finish()
        }

        findViewById<CardView>(R.id.btnBackToMenu).setOnClickListener {
            stopTTS()
            val intent = Intent(this, MathExercisesActivity::class.java)
            startActivity(intent)
            finish()
        }

        findViewById<ImageView>(R.id.btnBack).setOnClickListener {
            stopTTS()
            finish()
        }
    }

    private fun stopTTS() {
        tts?.stop()
    }

    override fun onDestroy() {
        tts?.stop()
        tts?.shutdown()
        super.onDestroy()
    }
}

package com.timursarsembayev.danabalanumbers

import android.content.Context
import android.content.Intent
import android.os.Bundle
import android.speech.tts.TextToSpeech
import android.widget.ImageView
import android.widget.TextView
import androidx.appcompat.app.AppCompatActivity
import androidx.cardview.widget.CardView
import androidx.core.view.ViewCompat
import androidx.core.view.WindowInsetsCompat
import java.util.*

class AudioMatchingResultsActivity : AppCompatActivity(), TextToSpeech.OnInitListener {

    private var tts: TextToSpeech? = null
    private var isTtsReady = false
    private var allowTts = true

    override fun attachBaseContext(newBase: Context?) {
        super.attachBaseContext(newBase?.let { LocaleManager.applyLanguage(it) })
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_audio_matching_results)

        ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main)) { v, insets ->
            val systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars())
            v.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom)
            insets
        }

        // Определяем язык и отключаем TTS для казахского
        val currentLang = LocaleManager.getCurrentLanguage(this).lowercase(Locale.ROOT)
        allowTts = currentLang != LocaleManager.LANGUAGE_KAZAKH

        if (allowTts) tts = TextToSpeech(this, this)

        setupViews()
        setupButtons()
    }

    override fun onInit(status: Int) {
        if (!allowTts) return
        if (status == TextToSpeech.SUCCESS) {
            val langCode = LocaleManager.getCurrentLanguage(this)
            val locale = when (langCode) {
                LocaleManager.LANGUAGE_RUSSIAN -> Locale.forLanguageTag("ru-RU")
                LocaleManager.LANGUAGE_ENGLISH -> Locale.forLanguageTag("en-US")
                else -> Locale.forLanguageTag("en-US")
            }
            val result = tts?.setLanguage(locale)
            isTtsReady = result != TextToSpeech.LANG_MISSING_DATA && result != TextToSpeech.LANG_NOT_SUPPORTED
            if (isTtsReady) speakCongratulation()
        }
    }

    private fun setupViews() {
        val completedLevels = intent.getIntExtra("completed_levels", 10)
        val correctActions = intent.getIntExtra("correct_actions", 0)
        val incorrectActions = intent.getIntExtra("incorrect_actions", 0)
        val finalScore = intent.getIntExtra("final_score", 0)

        findViewById<TextView>(R.id.completedLevelsText).text =
            getString(R.string.audio_matching_completed_levels_format, completedLevels)
        findViewById<TextView>(R.id.correctActionsText).text =
            getString(R.string.audio_matching_correct_actions_format, correctActions)
        findViewById<TextView>(R.id.incorrectActionsText).text =
            getString(R.string.audio_matching_incorrect_actions_format, incorrectActions)
        findViewById<TextView>(R.id.finalScoreText).text =
            getString(R.string.audio_matching_final_score_format, finalScore)

        val accuracy = if (correctActions + incorrectActions > 0) {
            (correctActions * 100) / (correctActions + incorrectActions)
        } else {
            100
        }

        val (messageRes, encouragementRes) = when {
            accuracy >= 90 -> R.string.audio_matching_result_excellent to R.string.audio_matching_result_excellent_desc
            accuracy >= 70 -> R.string.audio_matching_result_good to R.string.audio_matching_result_good_desc
            accuracy >= 50 -> R.string.audio_matching_result_ok to R.string.audio_matching_result_ok_desc
            else -> R.string.audio_matching_result_try to R.string.audio_matching_result_try_desc
        }

        findViewById<TextView>(R.id.resultMessage).setText(messageRes)
        findViewById<TextView>(R.id.encouragementText).setText(encouragementRes)
    }

    private fun speakCongratulation() {
        if (!allowTts || !isTtsReady) return
        val message = findViewById<TextView>(R.id.resultMessage).text.toString()
        tts?.speak(message, TextToSpeech.QUEUE_FLUSH, null, "audio_matching_results")
    }

    private fun setupButtons() {
        findViewById<CardView>(R.id.btnPlayAgain).setOnClickListener {
            stopTTS()
            val intent = Intent(this, AudioMatchingActivity::class.java)
            startActivity(intent)
            finish()
        }

        findViewById<CardView>(R.id.btnBackToMenu).setOnClickListener {
            stopTTS()
            val intent = Intent(this, MathExercisesActivity::class.java)
            startActivity(intent)
            finish()
        }

        findViewById<ImageView>(R.id.btnBack).setOnClickListener {
            stopTTS()
            finish()
        }
    }

    private fun stopTTS() {
        if (allowTts) tts?.stop()
    }

    override fun onDestroy() {
        if (allowTts) {
            tts?.stop()
            tts?.shutdown()
        }
        super.onDestroy()
    }
}

package com.timursarsembayev.danabalanumbers

import android.content.Intent
import android.os.Bundle
import android.view.View
import androidx.appcompat.app.AppCompatActivity
import androidx.cardview.widget.CardView
import androidx.core.view.ViewCompat
import androidx.core.view.WindowInsetsCompat
import com.google.android.material.tabs.TabLayout

class MathExercisesActivity : AppCompatActivity() {
    private val billing by lazy { (application as DanaBalApplication).billing }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_math_exercises)

        ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main)) { v, insets ->
            val systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars())
            v.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom)
            insets
        }

        setupTabs()
        setupExerciseCards()
        setupLanguageButton()
    }

    override fun attachBaseContext(newBase: android.content.Context?) {
        super.attachBaseContext(newBase?.let { LocaleManager.applyLanguage(it) })
    }

    private fun setupTabs() {
        val tabs = findViewById<TabLayout>(R.id.tabs)
        val trainings = findViewById<View>(R.id.trainingsContainer)
        val games = findViewById<View>(R.id.gamesContainer)

        // Добавляем вкладки
        val tabTrainings = tabs.newTab().setText(getString(R.string.tab_trainings))
        val tabGames = tabs.newTab().setText(getString(R.string.tab_games))
        tabs.addTab(tabTrainings)
        tabs.addTab(tabGames)

        // Начальное состояние: показываем тренировки
        trainings.visibility = View.VISIBLE
        games.visibility = View.GONE

        tabs.addOnTabSelectedListener(object : TabLayout.OnTabSelectedListener {
            override fun onTabSelected(tab: TabLayout.Tab) {
                val showGames = tab.position == 1
                if (showGames) {
                    animateSwitch(show = games, hide = trainings, fromRight = true)
                } else {
                    animateSwitch(show = trainings, hide = games, fromRight = false)
                }
            }
            override fun onTabUnselected(tab: TabLayout.Tab) {}
            override fun onTabReselected(tab: TabLayout.Tab) {}
        })
    }

    private fun animateSwitch(show: View, hide: View, fromRight: Boolean) {
        if (show === hide) return
        val distance = 32f * resources.displayMetrics.density
        val duration = 250L

        hide.clearAnimation()
        show.clearAnimation()

        show.alpha = 0f
        show.translationX = if (fromRight) distance else -distance
        show.visibility = View.VISIBLE

        show.animate()
            .alpha(1f)
            .translationX(0f)
            .setDuration(duration)
            .start()

        hide.animate()
            .alpha(0f)
            .translationX(if (fromRight) -distance else distance)
            .setDuration(duration)
            .withEndAction {
                hide.visibility = View.GONE
                hide.alpha = 1f
                hide.translationX = 0f
            }
            .start()
    }

    private fun openOrPaywall(clazz: Class<*>) {
        val intent = if (billing.isPremium()) Intent(this, clazz) else Intent(this, PaywallActivity::class.java)
        startActivity(intent)
    }

    private fun setupExerciseCards() {
        // Бесплатно: первые 4 тренировки
        findViewById<CardView>(R.id.cardNumberIntroduction).setOnClickListener {
            startActivity(Intent(this, NumberIntroductionActivity::class.java))
        }
        findViewById<CardView>(R.id.cardNumbers).setOnClickListener {
            startActivity(Intent(this, NumberRecognitionActivity::class.java))
        }
        findViewById<CardView>(R.id.cardCounting).setOnClickListener {
            startActivity(Intent(this, CountingActivity::class.java))
        }
        findViewById<CardView>(R.id.cardObjectCounting).setOnClickListener {
            startActivity(Intent(this, ObjectCountingActivity::class.java))
        }

        // Остальные тренировки — только в полной версии
        findViewById<CardView>(R.id.cardMatching).setOnClickListener {
            openOrPaywall(MatchingActivity::class.java)
        }
        findViewById<CardView>(R.id.cardAudioMatching).setOnClickListener {
            openOrPaywall(AudioMatchingActivity::class.java)
        }
        findViewById<CardView>(R.id.cardAscendingSequence).setOnClickListener {
            openOrPaywall(AscendingSequenceActivity::class.java)
        }
        findViewById<CardView>(R.id.cardDescendingSequence).setOnClickListener {
            openOrPaywall(DescendingSequenceActivity::class.java)
        }
        findViewById<CardView>(R.id.cardKidsComparison).setOnClickListener {
            openOrPaywall(KidsComparisonActivity::class.java)
        }
        findViewById<CardView>(R.id.cardNumberComparison).setOnClickListener {
            openOrPaywall(NumberComparisonActivity::class.java)
        }

        // Игры: бесплатно первые 2 (Рисование цифр, Шарики с цифрами)
        findViewById<CardView>(R.id.cardNumberDrawing).setOnClickListener {
            startActivity(Intent(this, NumberDrawingActivity::class.java))
        }
        findViewById<CardView>(R.id.cardBubbleCatch)?.setOnClickListener {
            startActivity(Intent(this, BubbleCatchActivity::class.java))
        }

        // Остальные игры — только в полной версии
        findViewById<CardView>(R.id.cardBlockMatch)?.setOnClickListener {
            openOrPaywall(BlockMatchActivity::class.java)
        }
        findViewById<CardView>(R.id.cardSchulteNumbers)?.setOnClickListener {
            openOrPaywall(SchulteNumbersActivity::class.java)
        }
        findViewById<CardView>(R.id.cardRowError)?.setOnClickListener {
            openOrPaywall(RowErrorActivity::class.java)
        }
        findViewById<CardView>(R.id.cardSnakeMath)?.setOnClickListener {
            openOrPaywall(SnakeMathActivity::class.java)
        }
        findViewById<CardView>(R.id.cardSorter)?.setOnClickListener {
            openOrPaywall(SorterActivity::class.java)
        }
        findViewById<CardView>(R.id.cardSudokuKids)?.setOnClickListener {
            openOrPaywall(SudokuKidsActivity::class.java)
        }
    }

    private fun setupLanguageButton() {
        // Добавим кнопку настроек языка в правый верхний угол
        val languageButton = findViewById<View>(R.id.languageButton)
        languageButton?.setOnClickListener {
            val intent = Intent(this, LanguageSettingsActivity::class.java)
            startActivity(intent)
        }
    }
}

