        checkButton.setOnClickListener { checkAnswer() }
        nextButton.setOnClickListener { nextQuestion() }

        // Добавляем обработчик для кнопки "Назад"
        findViewById<ImageButton>(R.id.backButton).setOnClickListener {
            finish()
        }

        // Изначально скрываем кнопку "Далее"
        nextButton.visibility = Button.GONE

        // Создаем символы сравнения
        createComparisonSymbols()
    }

    private fun createComparisonSymbols() {
        val symbols = arrayOf("<", ">", "=")

        symbols.forEach { symbol ->
            val symbolView = TextView(this).apply {
                text = symbol
                textSize = 28f  // Уменьшили с 32f до 28f
                setTextColor(ContextCompat.getColor(this@NumberComparisonActivity, android.R.color.black))
                setBackgroundResource(R.drawable.draggable_number_card)
                gravity = android.view.Gravity.CENTER
                setPadding(4, 4, 4, 4)
                includeFontPadding = false

                val layoutParams = LinearLayout.LayoutParams(70, 70).apply {
                    setMargins(8, 4, 8, 4)
                    gravity = android.view.Gravity.CENTER
                }
                this.layoutParams = layoutParams

                // Настройка drag functionality
                setOnTouchListener { view, event ->
                    if (event.action == MotionEvent.ACTION_DOWN) {
                        val clipData = ClipData.newPlainText("symbol", symbol)
                        val shadowBuilder = View.DragShadowBuilder(view)
                        view.startDragAndDrop(clipData, shadowBuilder, view, 0)
                        true
                    } else {
                        false
                    }
                }
            }
            comparisonSymbolsContainer.addView(symbolView)
        }
    }

    private fun setupDragAndDrop() {
        // Настройка drop zone для символов сравнения
        comparisonDropZone.setOnDragListener { view, event ->
            when (event.action) {
                DragEvent.ACTION_DRAG_STARTED -> true
                DragEvent.ACTION_DRAG_ENTERED -> {
                    view.setBackgroundResource(R.drawable.number_drop_zone_highlight)
                    true
                }
                DragEvent.ACTION_DRAG_EXITED -> {
                    resetDropZoneBackground()
                    true
                }
                DragEvent.ACTION_DROP -> {
                    val symbol = event.clipData.getItemAt(0).text.toString()
                    handleSymbolDrop(symbol)
                    true
                }
                DragEvent.ACTION_DRAG_ENDED -> {
                    resetDropZoneBackground()
                    true
                }
                else -> false
            }
        }

        // Клик по drop zone для возврата символа
        comparisonDropZone.setOnClickListener {
            returnSymbolToContainer()
        }

        // Настройка контейнера символов как drop zone для возврата
        comparisonSymbolsContainer.setOnDragListener { view, event ->
            when (event.action) {
                DragEvent.ACTION_DRAG_STARTED -> true
                DragEvent.ACTION_DRAG_ENTERED -> {
                    view.setBackgroundColor(ContextCompat.getColor(this, android.R.color.holo_blue_light))
                    view.alpha = 0.3f
                    true
                }
                DragEvent.ACTION_DRAG_EXITED -> {
                    view.setBackgroundColor(android.graphics.Color.TRANSPARENT)
                    view.alpha = 1.0f
                    true
                }
                DragEvent.ACTION_DROP -> {
                    view.setBackgroundColor(android.graphics.Color.TRANSPARENT)
                    view.alpha = 1.0f
                    returnSymbolToContainer()
                    true
                }
                DragEvent.ACTION_DRAG_ENDED -> {
                    view.setBackgroundColor(android.graphics.Color.TRANSPARENT)
                    view.alpha = 1.0f
                    true
                }
                else -> false
            }
        }
    }

    private fun handleSymbolDrop(symbol: String) {
        // Если уже есть символ, возвращаем его
        if (selectedSymbol.isNotEmpty()) {
            returnSymbolToContainer()
        }

        // Устанавливаем новый символ
        selectedSymbol = symbol
        comparisonDropZone.text = symbol
        comparisonDropZone.setBackgroundResource(R.drawable.number_drop_zone_filled)

        // Удаляем символ из контейнера
        removeSymbolFromContainer(symbol)

        // Активируем кнопку проверки
        checkButton.isEnabled = true

        // Озвучиваем вопрос с добавленным символом
        speakComparisonQuestion(symbol)
    }

    private fun returnSymbolToContainer() {
        if (selectedSymbol.isNotEmpty()) {
            // Очищаем drop zone
            comparisonDropZone.text = ""
            comparisonDropZone.setBackgroundResource(R.drawable.number_drop_zone)

            // Возвращаем символ в контейнер
            addSymbolToContainer(selectedSymbol)

            selectedSymbol = ""
            checkButton.isEnabled = false
        }
    }

    private fun removeSymbolFromContainer(symbol: String) {
        for (i in 0 until comparisonSymbolsContainer.childCount) {
            val child = comparisonSymbolsContainer.getChildAt(i) as TextView
            if (child.text.toString() == symbol) {
                comparisonSymbolsContainer.removeView(child)
                break
            }
        }
    }

    private fun addSymbolToContainer(symbol: String) {
        val symbolView = TextView(this).apply {
            text = symbol
            textSize = 28f  // Изменили с 32f на 28f для соответствия
            setTextColor(ContextCompat.getColor(this@NumberComparisonActivity, android.R.color.black))
            setBackgroundResource(R.drawable.draggable_number_card)
            gravity = android.view.Gravity.CENTER
            setPadding(4, 4, 4, 4)
            includeFontPadding = false

            val layoutParams = LinearLayout.LayoutParams(70, 70).apply {
                setMargins(8, 4, 8, 4)
                gravity = android.view.Gravity.CENTER
            }
            this.layoutParams = layoutParams

            setOnTouchListener { view, event ->
                if (event.action == MotionEvent.ACTION_DOWN) {
                    val clipData = ClipData.newPlainText("symbol", symbol)
                    val shadowBuilder = View.DragShadowBuilder(view)
                    view.startDragAndDrop(clipData, shadowBuilder, view, 0)
                    true
                } else {
                    false
                }
            }
        }

        // Вставляем символ в правильном порядке
        val symbols = arrayOf("<", ">", "=")
        val position = symbols.indexOf(symbol)
        if (position != -1 && position <= comparisonSymbolsContainer.childCount) {
            comparisonSymbolsContainer.addView(symbolView, position)
        } else {
            comparisonSymbolsContainer.addView(symbolView)
        }
    }

    private fun resetDropZoneBackground() {
        if (comparisonDropZone.text.isEmpty()) {
            comparisonDropZone.setBackgroundResource(R.drawable.number_drop_zone)
        } else {
            comparisonDropZone.setBackgroundResource(R.drawable.number_drop_zone_filled)
        }
    }

    private fun generateNewQuestion() {
        hasTriedCurrentQuestion = false
        checkButton.isEnabled = false
        nextButton.visibility = Button.GONE

        // Очищаем предыдущее состояние
        returnSymbolToContainer()

        // Генерируем два разных числа от 0 до 9
        do {
            leftNumber = Random.nextInt(10)
            rightNumber = Random.nextInt(10)
        } while (leftNumber == rightNumber) // Убеждаемся, что числа разные для начала

        // В 30% случаев делаем числа равными
        if (Random.nextFloat() < 0.3f) {
            rightNumber = leftNumber
        }

        // Выбираем случайный объект
        currentObjectType = objectEmojis[Random.nextInt(objectEmojis.size)]

        // Определяем правильный символ сравнения
        correctComparison = when {
            leftNumber < rightNumber -> "<"
            leftNumber > rightNumber -> ">"
            else -> "="
        }

        // Обновляем отображение
        leftNumberDisplay.text = leftNumber.toString()
        rightNumberDisplay.text = rightNumber.toString()

        leftObjectsDisplay.text = generateObjects(leftNumber)
        rightObjectsDisplay.text = generateObjects(rightNumber)

        updateProgress()
        updateQuestionText()
        speakQuestion()
    }

    private fun generateObjects(count: Int): String {
        if (count == 0) return ""

        // Отображаем все предметы в одну строку
        return currentObjectType.repeat(count)
    }

    private fun updateQuestionText() {
        questionText.text = getString(R.string.number_comparison_question)
        hintText.text = getString(R.string.number_comparison_hint_drag_symbol)
    }

    private fun updateProgress() {
        progressBar.progress = ((currentQuestion.toFloat() / totalQuestions) * 100).toInt()
    }

    private fun checkAnswer() {
        if (!hasTriedCurrentQuestion) {
            hasTriedCurrentQuestion = true
        }

        if (selectedSymbol == correctComparison) {
            // Правильный ответ
            score += 100
            totalCorrectAnswers++
            showCorrectFeedback()
            checkButton.isEnabled = false
            nextButton.visibility = Button.VISIBLE

            comparisonDropZone.setBackgroundResource(R.drawable.number_input_correct)
            animateCorrectAnswer(comparisonDropZone)
        } else {
            // Неправильный ответ
            showIncorrectFeedback()
            comparisonDropZone.setBackgroundResource(R.drawable.number_input_incorrect)
            animateIncorrectAnswer(comparisonDropZone)
        }
    }

    private fun showCorrectFeedback() {
        val phrase = correctPhrases.random()
        hintText.text = phrase
        hintText.setTextColor(ContextCompat.getColor(this, android.R.color.holo_green_dark))
        speakText(phrase)
    }

    private fun showIncorrectFeedback() {
        hintText.text = getString(R.string.number_comparison_try_again)
        hintText.setTextColor(ContextCompat.getColor(this, android.R.color.holo_red_dark))
        speakText(getString(R.string.number_comparison_try_again_short))
    }

    private fun nextQuestion() {
        currentQuestion++

        if (currentQuestion >= totalQuestions) {
            finishGame()
        } else {
            generateNewQuestion()
        }
    }

    private fun finishGame() {
        val intent = Intent(this, NumberComparisonResultsActivity::class.java)
        intent.putExtra("score", score)
        intent.putExtra("totalCorrectAnswers", totalCorrectAnswers)
        intent.putExtra("totalQuestions", totalQuestions)
        startActivity(intent)
        finish()
    }

    private fun animateCorrectAnswer(view: TextView) {
        val scaleX = ObjectAnimator.ofFloat(view, "scaleX", 1f, 1.2f, 1f)
        val scaleY = ObjectAnimator.ofFloat(view, "scaleY", 1f, 1.2f, 1f)
        val animatorSet = AnimatorSet()
        animatorSet.playTogether(scaleX, scaleY)
        animatorSet.duration = 300
        animatorSet.start()
    }

    private fun animateIncorrectAnswer(view: TextView) {
        val shake = ObjectAnimator.ofFloat(view, "translationX", 0f, -10f, 10f, -5f, 5f, 0f)
        shake.duration = 500
        shake.start()
    }

    private fun speakQuestion() {
        if (tts == null) return
        val leftDescription = getNumberDescription(leftNumber)
        val rightDescription = getNumberDescription(rightNumber)
        val template = getString(R.string.number_comparison_tts_compare_template)
        speakText(String.format(template, leftDescription, rightDescription))
    }

    private fun speakComparisonQuestion(symbol: String) {
        if (tts == null) return
        val leftDescription = getNumberDescription(leftNumber)
        val rightDescription = getNumberDescription(rightNumber)

        val symbolDescription = when (symbol) {
            "<" -> getString(R.string.less_than_word)
            ">" -> getString(R.string.greater_than_word)
            "=" -> getString(R.string.equals_word)
            else -> symbol
        }

        val encouragement = encouragementPhrases.random()
        val template = getString(R.string.number_comparison_tts_compare_with_symbol_template)
        val question = String.format(template, leftDescription, symbolDescription, rightDescription, encouragement)
        speakText(question)
    }

    private fun getNumberDescription(number: Int): String {
        return when (number) {
            0 -> getString(R.string.number_name_0)
            1 -> getString(R.string.number_name_1)
            2 -> getString(R.string.number_name_2)
            3 -> getString(R.string.number_name_3)
            4 -> getString(R.string.number_name_4)
            5 -> getString(R.string.number_name_5)
            6 -> getString(R.string.number_name_6)
            7 -> getString(R.string.number_name_7)
            8 -> getString(R.string.number_name_8)
            9 -> getString(R.string.number_name_9)
            else -> number.toString()
        }
    }

    private fun speakText(text: String) {
        tts?.speak(text, TextToSpeech.QUEUE_FLUSH, null, null)
    }

    override fun onInit(status: Int) {
        if (status == TextToSpeech.SUCCESS) {
            val lang = LocaleManager.getCurrentLanguage(this)
            val locale = when (lang) {
                LocaleManager.LANGUAGE_ENGLISH -> Locale.forLanguageTag("en-US")
                else -> Locale.forLanguageTag("ru-RU")
            }
            val result = tts!!.setLanguage(locale)
            if (result == TextToSpeech.LANG_MISSING_DATA || result == TextToSpeech.LANG_NOT_SUPPORTED) {
                tts!!.setLanguage(Locale.getDefault())
            }
            speakQuestion()
        }
    }

    override fun onDestroy() {
        tts?.stop()
        tts?.shutdown()
        super.onDestroy()
    }
}

package com.timursarsembayev.danabalanumbers

import android.content.Intent
import android.content.pm.ActivityInfo
import android.os.Bundle
import android.speech.tts.TextToSpeech
import android.widget.Button
import android.widget.ImageButton
import android.widget.LinearLayout
import android.widget.TextView
import androidx.appcompat.app.AppCompatActivity
import androidx.core.content.ContextCompat
import androidx.core.view.ViewCompat
import androidx.core.view.WindowInsetsCompat
import java.util.*

class NumberComparisonResultsActivity : AppCompatActivity(), TextToSpeech.OnInitListener {

    private var tts: TextToSpeech? = null

    // Варианты поздравлений для разных уровней успеха
    private val excellentPhrases = listOf(
        "Поздравляю! Ты настоящий чемпион по сравнению чисел!",
        "Невероятно! Ты отлично знаешь, какие числа больше, а какие меньше!",
        "Браво! Ты справился просто великолепно!",
        "Супер! Ты становишься настоящим математиком!"
    )

    private val goodPhrases = listOf(
        "Молодец! Ты хорошо понимаешь сравнение чисел!",
        "Отлично! Продолжай в том же духе!",
        "Здорово! Ты делаешь большие успехи!",
        "Умница! Ты очень хорошо справился!"
    )

    private val okayPhrases = listOf(
        "Неплохо! Продолжай тренироваться, и у тебя все получится!",
        "Хорошая попытка! Ты на правильном пути!",
        "Так держать! С каждым разом у тебя получается лучше!",
        "Молодец, что стараешься! Продолжай изучать числа!"
    )

    private val encouragementPhrases = listOf(
        "Не расстраивайся! Все учатся постепенно. Попробуй еще раз!",
        "Ничего страшного! Каждый математик начинал с простых заданий!",
        "Не сдавайся! Ты обязательно научишься сравнивать числа!",
        "Попробуй снова! У тебя все получится!"
    )

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)

        // Принудительно устанавливаем альбомную ориентацию
        requestedOrientation = ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE

        setContentView(R.layout.activity_number_comparison_results)

        ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main)) { v, insets ->
            val systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars())
            v.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom)
            insets
        }

        tts = TextToSpeech(this, this)
        setupViews()
    }

    private fun setupViews() {
        val score = intent.getIntExtra("score", 0)
        val totalCorrectAnswers = intent.getIntExtra("totalCorrectAnswers", 0)
        val totalQuestions = intent.getIntExtra("totalQuestions", 20)
        val fromKidsComparison = intent.getBooleanExtra("fromKidsComparison", false)

        val scoreDisplay = findViewById<TextView>(R.id.scoreDisplay)
        val correctAnswersDisplay = findViewById<TextView>(R.id.correctAnswersDisplay)
        val accuracyDisplay = findViewById<TextView>(R.id.accuracyDisplay)
        val messageDisplay = findViewById<TextView>(R.id.messageDisplay)
        val motivationalMessage = findViewById<TextView>(R.id.motivationalMessage)
        val performanceBadge = findViewById<TextView>(R.id.performanceBadge)
        val congratulationsIcon = findViewById<TextView>(R.id.congratulationsIcon)
        val achievementStars = findViewById<LinearLayout>(R.id.achievementStars)

        scoreDisplay.text = "Очки: $score"
        correctAnswersDisplay.text = "Правильных ответов: $totalCorrectAnswers из $totalQuestions"

        val accuracy = if (totalQuestions > 0) {
            (totalCorrectAnswers.toFloat() / totalQuestions * 100).toInt()
        } else 0

        accuracyDisplay.text = "Точность: $accuracy%"

        // Настройка сообщений и внешнего вида в зависимости от результата
        when {
            accuracy >= 90 -> {
                messageDisplay.text = " Поздравляем! Ты чемпион!"
                motivationalMessage.text = "Ты отлично знаешь, как сравнивать числа! Продолжай изучать математику!"
                performanceBadge.text = " ПРЕВОСХОДНО!"
                congratulationsIcon.text = ""
                createStars(achievementStars, 5)
            }
            accuracy >= 75 -> {
                messageDisplay.text = " Отлично! Очень хорошо!"
                motivationalMessage.text = "Ты хорошо понимаешь сравнение чисел! Так держать!"
                performanceBadge.text = " ОТЛИЧНО!"
                congratulationsIcon.text = ""
                createStars(achievementStars, 4)
            }
            accuracy >= 50 -> {
                messageDisplay.text = " Хорошая попытка!"
                motivationalMessage.text = "Ты на правильном пути! Продолжай тренироваться!"
                performanceBadge.text = " ХОРОШО!"
                congratulationsIcon.text = ""
                createStars(achievementStars, 3)
            }
            else -> {
                messageDisplay.text = " Попробуй еще раз!"
                motivationalMessage.text = "Не расстраивайся! Все учатся постепенно. Ты обязательно справишься!"
                performanceBadge.text = " СТАРАЙСЯ!"
                congratulationsIcon.text = ""
                createStars(achievementStars, 2)
            }
        }

        // Кнопки
        findViewById<Button>(R.id.restartButton).setOnClickListener {
            val intent = Intent(this, if (fromKidsComparison) KidsComparisonActivity::class.java else NumberComparisonActivity::class.java)
            startActivity(intent)
            finish()
        }

        findViewById<Button>(R.id.homeButton).setOnClickListener {
            val intent = Intent(this, MathExercisesActivity::class.java)
            intent.flags = Intent.FLAG_ACTIVITY_CLEAR_TOP
            startActivity(intent)
            finish()
        }

        findViewById<ImageButton>(R.id.backButton).setOnClickListener {
            finish()
        }
    }

    private fun createStars(container: LinearLayout, count: Int) {
        container.removeAllViews()

        for (i in 1..5) {
            val star = TextView(this).apply {
                text = if (i <= count) "⭐" else "☆"
                textSize = 24f
                setPadding(4, 0, 4, 0)
            }
            container.addView(star)
        }
    }

    private fun speakCongratulations(accuracy: Int) {
        val congratulationPhrase = when {
            accuracy >= 90 -> excellentPhrases.random()
            accuracy >= 75 -> goodPhrases.random()
            accuracy >= 50 -> okayPhrases.random()
            else -> encouragementPhrases.random()
        }

        speakText(congratulationPhrase)
    }

    private fun speakText(text: String) {
        tts?.speak(text, TextToSpeech.QUEUE_ADD, null, null)
    }

    override fun onInit(status: Int) {
        if (status == TextToSpeech.SUCCESS) {
            val result = tts!!.setLanguage(Locale("ru", "RU"))
            if (result == TextToSpeech.LANG_MISSING_DATA || result == TextToSpeech.LANG_NOT_SUPPORTED) {
                tts!!.setLanguage(Locale.getDefault())
            }

            // Озвучиваем поздравления через секунду после инициализации TTS
            val accuracy = if (intent.getIntExtra("totalQuestions", 20) > 0) {
                (intent.getIntExtra("totalCorrectAnswers", 0).toFloat() / intent.getIntExtra("totalQuestions", 20) * 100).toInt()
            } else 0

            // Небольшая задержка для лучшего восприятия
            android.os.Handler(mainLooper).postDelayed({
                speakCongratulations(accuracy)
            }, 1000)
        }
    }

    override fun onDestroy() {
        tts?.stop()
        tts?.shutdown()
        super.onDestroy()
    }
}

package com.timursarsembayev.danabalanumbers

import android.content.Context
import android.content.Intent
import android.content.pm.ActivityInfo
import android.os.Bundle
import android.speech.tts.TextToSpeech
import android.widget.Button
import android.widget.ImageButton
import android.widget.LinearLayout
import android.widget.TextView
import androidx.appcompat.app.AppCompatActivity
import androidx.core.view.ViewCompat
import androidx.core.view.WindowInsetsCompat
import java.util.*

class NumberComparisonResultsActivity : AppCompatActivity(), TextToSpeech.OnInitListener {

    private var tts: TextToSpeech? = null

    // Фразы для TTS берем из ресурсов
    private val excellentPhrases by lazy { resources.getStringArray(R.array.number_comparison_results_excellent_phrases).toList() }
    private val goodPhrases by lazy { resources.getStringArray(R.array.number_comparison_results_good_phrases).toList() }
    private val okayPhrases by lazy { resources.getStringArray(R.array.number_comparison_results_okay_phrases).toList() }
    private val encouragementPhrases by lazy { resources.getStringArray(R.array.number_comparison_results_encouragement_phrases).toList() }

    override fun attachBaseContext(newBase: Context) {
        val ctx = LocaleManager.applyLanguage(newBase)
        super.attachBaseContext(ctx)
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)

        // Принудительно устанавливаем альбомную ориентацию
        requestedOrientation = ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE

        setContentView(R.layout.activity_number_comparison_results)

        ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main)) { v, insets ->
            val systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars())
            v.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom)
            insets
        }

        // Инициализируем TTS только для ru/en; для kk — отключаем полностью
        val lang = LocaleManager.getCurrentLanguage(this)
        if (lang != LocaleManager.LANGUAGE_KAZAKH) {
            tts = TextToSpeech(this, this)
        }

        setupViews()
    }

    private fun setupViews() {
        val score = intent.getIntExtra("score", 0)
        val totalCorrectAnswers = intent.getIntExtra("totalCorrectAnswers", 0)
        val totalQuestions = intent.getIntExtra("totalQuestions", 20)
        val fromKidsComparison = intent.getBooleanExtra("fromKidsComparison", false)

        val scoreDisplay = findViewById<TextView>(R.id.scoreDisplay)
        val correctAnswersDisplay = findViewById<TextView>(R.id.correctAnswersDisplay)
        val accuracyDisplay = findViewById<TextView>(R.id.accuracyDisplay)
        val messageDisplay = findViewById<TextView>(R.id.messageDisplay)
        val motivationalMessage = findViewById<TextView>(R.id.motivationalMessage)
        val performanceBadge = findViewById<TextView>(R.id.performanceBadge)
        val congratulationsIcon = findViewById<TextView>(R.id.congratulationsIcon)
        val achievementStars = findViewById<LinearLayout>(R.id.achievementStars)

        scoreDisplay.text = getString(R.string.number_comparison_score_points, score)
        correctAnswersDisplay.text = getString(R.string.number_comparison_correct_answers_format, totalCorrectAnswers, totalQuestions)

        val accuracy = if (totalQuestions > 0) {
            (totalCorrectAnswers.toFloat() / totalQuestions * 100).toInt()
        } else 0

        accuracyDisplay.text = getString(R.string.number_comparison_accuracy_format, accuracy)

        // Настройка сообщений и внешнего вида в зависимости от результата
        when {
            accuracy >= 90 -> {
                messageDisplay.text = getString(R.string.number_comparison_results_title_excellent)
                motivationalMessage.text = getString(R.string.number_comparison_results_message_excellent)
                performanceBadge.text = getString(R.string.number_comparison_results_badge_excellent)
                congratulationsIcon.text = ""
                createStars(achievementStars, 5)
            }
            accuracy >= 75 -> {
                messageDisplay.text = getString(R.string.number_comparison_results_title_good)
                motivationalMessage.text = getString(R.string.number_comparison_results_message_good)
                performanceBadge.text = getString(R.string.number_comparison_results_badge_good)
                congratulationsIcon.text = ""
                createStars(achievementStars, 4)
            }
            accuracy >= 50 -> {
                messageDisplay.text = getString(R.string.number_comparison_results_title_okay)
                motivationalMessage.text = getString(R.string.number_comparison_results_message_okay)
                performanceBadge.text = getString(R.string.number_comparison_results_badge_okay)
                congratulationsIcon.text = ""
                createStars(achievementStars, 3)
            }
            else -> {
                messageDisplay.text = getString(R.string.number_comparison_results_title_try_again)
                motivationalMessage.text = getString(R.string.number_comparison_results_message_try_again)
                performanceBadge.text = getString(R.string.number_comparison_results_badge_try_again)
                congratulationsIcon.text = ""
                createStars(achievementStars, 2)
            }
        }

        // Кнопки
        findViewById<Button>(R.id.restartButton).setOnClickListener {
            val intent = Intent(this, if (fromKidsComparison) KidsComparisonActivity::class.java else NumberComparisonActivity::class.java)
            startActivity(intent)
            finish()
        }

        findViewById<Button>(R.id.homeButton).setOnClickListener {
            val intent = Intent(this, MathExercisesActivity::class.java)
            intent.flags = Intent.FLAG_ACTIVITY_CLEAR_TOP
            startActivity(intent)
            finish()
        }

        findViewById<ImageButton>(R.id.backButton).setOnClickListener {
            finish()
        }
    }

    private fun createStars(container: LinearLayout, count: Int) {
        container.removeAllViews()

        for (i in 1..5) {
            val star = TextView(this).apply {
                text = if (i <= count) "⭐" else "☆"
                textSize = 24f
                setPadding(4, 0, 4, 0)
            }
            container.addView(star)
        }
    }

    private fun speakCongratulations(accuracy: Int) {
        val congratulationPhrase = when {
            accuracy >= 90 -> excellentPhrases.random()
            accuracy >= 75 -> goodPhrases.random()
            accuracy >= 50 -> okayPhrases.random()
            else -> encouragementPhrases.random()
        }

        speakText(congratulationPhrase)
    }

    private fun speakText(text: String) {
        tts?.speak(text, TextToSpeech.QUEUE_ADD, null, null)
    }

    override fun onInit(status: Int) {
        if (status == TextToSpeech.SUCCESS) {
            val lang = LocaleManager.getCurrentLanguage(this)
            val locale = when (lang) {
                LocaleManager.LANGUAGE_ENGLISH -> Locale.forLanguageTag("en-US")
                else -> Locale.forLanguageTag("ru-RU")
            }
            val result = tts!!.setLanguage(locale)
            if (result == TextToSpeech.LANG_MISSING_DATA || result == TextToSpeech.LANG_NOT_SUPPORTED) {
                tts!!.setLanguage(Locale.getDefault())
            }

            // Озвучиваем поздравления через секунду после инициализации TTS
            val accuracy = if (intent.getIntExtra("totalQuestions", 20) > 0) {
                (intent.getIntExtra("totalCorrectAnswers", 0).toFloat() / intent.getIntExtra("totalQuestions", 20) * 100).toInt()
            } else 0

            // Небольшая задержка для лучшего восприятия
            android.os.Handler(mainLooper).postDelayed({
                speakCongratulations(accuracy)
            }, 1000)
        }
    }

    override fun onDestroy() {
        tts?.stop()
        tts?.shutdown()
        super.onDestroy()
    }
}

package com.timursarsembayev.danabalanumbers

import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import androidx.cardview.widget.CardView
import androidx.recyclerview.widget.RecyclerView

class AudioButtonsAdapter(
    private var items: MutableList<MatchingItem>,
    private val onItemClick: (MatchingItem, View) -> Unit
) : RecyclerView.Adapter<AudioButtonsAdapter.AudioButtonViewHolder>() {

    class AudioButtonViewHolder(itemView: View) : RecyclerView.ViewHolder(itemView) {
        val cardView: CardView = itemView.findViewById(R.id.cardView)
    }

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): AudioButtonViewHolder {
        val view = LayoutInflater.from(parent.context).inflate(R.layout.item_audio_button, parent, false)
        return AudioButtonViewHolder(view)
    }

    override fun onBindViewHolder(holder: AudioButtonViewHolder, position: Int) {
        val item = items[position]

        // Устанавливаем прозрачность для сопоставленных элементов
        holder.cardView.alpha = if (item.isMatched) 0.3f else 1.0f

        holder.cardView.setOnClickListener {
            if (!item.isMatched) {
                // Простой эффект нажатия
                holder.cardView.animate().scaleX(0.95f).scaleY(0.95f).setDuration(100)
                    .withEndAction {
                        holder.cardView.animate().scaleX(1.0f).scaleY(1.0f).setDuration(100).start()
                    }.start()

                onItemClick(item, holder.cardView)
            }
        }
    }

    override fun getItemCount(): Int = items.size

    fun updateItems(newItems: List<MatchingItem>) {
        items.clear()
        items.addAll(newItems)
        notifyDataSetChanged()
    }

    fun removeItem(item: MatchingItem) {
        val position = items.indexOf(item)
        if (position != -1) {
            items.removeAt(position)
            notifyItemRemoved(position)
        }
    }
}

package com.timursarsembayev.danabalanumbers

import android.animation.Animator
import android.animation.AnimatorListenerAdapter
import android.animation.ValueAnimator
import android.content.Intent
import android.os.Bundle
import android.speech.tts.TextToSpeech
import android.view.View
import android.widget.ImageView
import android.widget.LinearLayout
import android.widget.ProgressBar
import android.widget.TextView
import androidx.appcompat.app.AppCompatActivity
import androidx.recyclerview.widget.LinearLayoutManager
import androidx.recyclerview.widget.RecyclerView
import java.util.Locale
import kotlin.random.Random

class AudioMatchingActivity : AppCompatActivity(), TextToSpeech.OnInitListener {

    private lateinit var audioButtonsRecyclerView: RecyclerView
    private lateinit var numbersRecyclerView: RecyclerView
    private lateinit var audioButtonsAdapter: AudioButtonsAdapter
    private lateinit var numbersAdapter: NumbersAdapter
    private lateinit var progressBar: ProgressBar
    private lateinit var backButton: ImageView

    private var currentLevel = 1
    private var totalLevels = 10
    private var levels = mutableListOf<AudioMatchingLevel>()
    private var currentLevelData: AudioMatchingLevel? = null

    private var selectedAudioItem: MatchingItem? = null
    private var selectedNumberItem: MatchingItem? = null
    private var selectedAudioView: View? = null
    private var selectedNumberView: View? = null

    private var completedMatches = 0
    private var correctActions = 0
    private var incorrectActions = 0

    private lateinit var tts: TextToSpeech
    private var isTtsReady = false

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_audio_matching)

        initTTS()
        initViews()
        initData()
        setupRecyclerViews()
        loadLevel(currentLevel)
    }

    private fun initTTS() {
        tts = TextToSpeech(this, this)
    }

    override fun onInit(status: Int) {
        if (status == TextToSpeech.SUCCESS) {
            val result = tts.setLanguage(Locale("ru"))
            isTtsReady = result != TextToSpeech.LANG_MISSING_DATA && result != TextToSpeech.LANG_NOT_SUPPORTED
        }
    }

    private fun speakNumber(number: Int) {
        if (isTtsReady) {
            val numberText = when (number) {
                1 -> "один"
                2 -> "два"
                3 -> "три"
                4 -> "четыре"
                5 -> "пять"
                6 -> "шесть"
                7 -> "семь"
                8 -> "восемь"
                9 -> "девять"
                else -> number.toString()
            }
            tts.speak(numberText, TextToSpeech.QUEUE_FLUSH, null, null)
        }
    }

    private fun speakText(text: String) {
        if (isTtsReady) {
            tts.speak(text, TextToSpeech.QUEUE_FLUSH, null, null)
        }
    }

    private fun initViews() {
        audioButtonsRecyclerView = findViewById(R.id.audioButtonsRecyclerView)
        numbersRecyclerView = findViewById(R.id.numbersRecyclerView)
        progressBar = findViewById(R.id.progressBar)
        backButton = findViewById(R.id.backButton)

        backButton.setOnClickListener {
            finish()
        }
    }

    private fun initData() {
        levels = AudioMatchingGameData.generateAllLevels().toMutableList()
    }

    private fun setupRecyclerViews() {
        audioButtonsAdapter = AudioButtonsAdapter(mutableListOf()) { item, view ->
            onAudioButtonClick(item, view)
        }

        numbersAdapter = NumbersAdapter(mutableListOf()) { item, view ->
            onNumberItemClick(item, view)
        }

        audioButtonsRecyclerView.apply {
            layoutManager = LinearLayoutManager(this@AudioMatchingActivity)
            adapter = audioButtonsAdapter
        }

        numbersRecyclerView.apply {
            layoutManager = LinearLayoutManager(this@AudioMatchingActivity)
            adapter = numbersAdapter
        }
    }

    private fun loadLevel(level: Int) {
        currentLevelData = levels[level - 1]
        updateProgressBar()
        completedMatches = 0

        // Перемешиваем элементы для случайного порядка
        val audioButtons = currentLevelData!!.pairs.map { it.number }.shuffled()
        val numbers = currentLevelData!!.pairs.map { it.number }.shuffled()

        audioButtonsAdapter.updateItems(audioButtons)
        numbersAdapter.updateItems(numbers)

        clearSelections()
        resetViewsAlpha()
    }

    private fun updateProgressBar() {
        val progress = (currentLevel * 100) / totalLevels
        progressBar.progress = progress
    }

    private fun resetViewsAlpha() {
        audioButtonsRecyclerView.post {
            for (i in 0 until audioButtonsRecyclerView.childCount) {
                val child = audioButtonsRecyclerView.getChildAt(i)
                child.alpha = 1.0f
                child.scaleX = 1.0f
                child.scaleY = 1.0f
            }
        }

        numbersRecyclerView.post {
            for (i in 0 until numbersRecyclerView.childCount) {
                val child = numbersRecyclerView.getChildAt(i)
                child.alpha = 1.0f
                child.scaleX = 1.0f
                child.scaleY = 1.0f
            }
        }
    }

    private fun onAudioButtonClick(item: MatchingItem, view: View) {
        if (item.isMatched) return

        // Озвучиваем число
        speakNumber(item.value)

        // Убираем предыдущее выделение
        selectedAudioView?.let { prevView ->
            val linearLayout = prevView.findViewById<LinearLayout>(R.id.audioButtonLayout)
            linearLayout?.setBackgroundColor(androidx.core.content.ContextCompat.getColor(this, android.R.color.white))
        }

        if (selectedAudioItem == item) {
            clearSelections()
            return
        }

        selectedAudioItem = item
        selectedAudioView = view

        // Выделяем элемент зеленым цветом
        val linearLayout = view.findViewById<LinearLayout>(R.id.audioButtonLayout)
        linearLayout?.setBackgroundColor(androidx.core.content.ContextCompat.getColor(this, android.R.color.holo_green_light))

        checkMatch()
    }

    private fun onNumberItemClick(item: MatchingItem, view: View) {
        if (item.isMatched) return

        // Убираем предыдущее выделение
        selectedNumberView?.let { prevView ->
            val numberText = prevView.findViewById<TextView>(R.id.numberText)
            numberText?.setBackgroundColor(androidx.core.content.ContextCompat.getColor(this, R.color.button_color))
        }

        if (selectedNumberItem == item) {
            clearSelections()
            return
        }

        selectedNumberItem = item
        selectedNumberView = view

        // Выделяем элемент зеленым цветом
        val numberText = view.findViewById<TextView>(R.id.numberText)
        numberText?.setBackgroundColor(androidx.core.content.ContextCompat.getColor(this, android.R.color.holo_green_light))

        checkMatch()
    }

    private fun checkMatch() {
        val audioItem = selectedAudioItem
        val numberItem = selectedNumberItem

        if (audioItem != null && numberItem != null) {
            if (audioItem.value == numberItem.value) {
                onCorrectMatch(audioItem, numberItem)
            } else {
                onIncorrectMatch()
            }
        }
    }

    private fun onCorrectMatch(audioItem: MatchingItem, numberItem: MatchingItem) {
        correctActions++

        val randomPhrase = MatchingFeedbackPhrases.correctPhrases[Random.nextInt(MatchingFeedbackPhrases.correctPhrases.size)]
        speakText(randomPhrase)

        audioItem.isMatched = true
        numberItem.isMatched = true

        animateMatch(selectedAudioView!!, selectedNumberView!!) {
            audioButtonsAdapter.removeItem(audioItem)
            numbersAdapter.removeItem(numberItem)

            completedMatches++

            if (completedMatches >= 5) {
                onLevelCompleted()
            }
        }

        clearSelections()
    }

    private fun onIncorrectMatch() {
        incorrectActions++

        val randomPhrase = MatchingFeedbackPhrases.incorrectPhrases[Random.nextInt(MatchingFeedbackPhrases.incorrectPhrases.size)]
        speakText(randomPhrase)

        // Выделяем обе карточки красным цветом на полсекунды
        selectedAudioView?.let { view ->
            val linearLayout = view.findViewById<LinearLayout>(R.id.audioButtonLayout)
            linearLayout?.setBackgroundColor(androidx.core.content.ContextCompat.getColor(this, android.R.color.holo_red_light))
        }

        selectedNumberView?.let { view ->
            val numberText = view.findViewById<TextView>(R.id.numberText)
            numberText?.setBackgroundColor(androidx.core.content.ContextCompat.getColor(this, android.R.color.holo_red_light))
        }

        // Через 500ms возвращаем зеленое выделение
        android.os.Handler(android.os.Looper.getMainLooper()).postDelayed({
            selectedAudioView?.let { view ->
                val linearLayout = view.findViewById<LinearLayout>(R.id.audioButtonLayout)
                linearLayout?.setBackgroundColor(androidx.core.content.ContextCompat.getColor(this, android.R.color.holo_green_light))
            }

            selectedNumberView?.let { view ->
                val numberText = view.findViewById<TextView>(R.id.numberText)
                numberText?.setBackgroundColor(androidx.core.content.ContextCompat.getColor(this, android.R.color.holo_green_light))
            }
        }, 500)

        animateIncorrectMatch(selectedAudioView!!, selectedNumberView!!)
    }

    private fun animateMatch(view1: View, view2: View, onComplete: () -> Unit) {
        val animator1 = ValueAnimator.ofFloat(1f, 0f)
        val animator2 = ValueAnimator.ofFloat(1f, 0f)

        animator1.duration = 300
        animator2.duration = 300

        animator1.addUpdateListener { animation ->
            val alpha = animation.animatedValue as Float
            view1.alpha = alpha
            view1.scaleX = alpha
            view1.scaleY = alpha
        }

        animator2.addUpdateListener { animation ->
            val alpha = animation.animatedValue as Float
            view2.alpha = alpha
            view2.scaleX = alpha
            view2.scaleY = alpha
        }

        animator1.addListener(object : AnimatorListenerAdapter() {
            override fun onAnimationEnd(animation: Animator) {
                onComplete()
            }
        })

        animator1.start()
        animator2.start()
    }

    private fun animateIncorrectMatch(view1: View, view2: View) {
        val shake = ValueAnimator.ofFloat(0f, 25f, -25f, 25f, -25f, 15f, -15f, 6f, -6f, 0f)
        shake.duration = 600

        shake.addUpdateListener { animation ->
            val translateX = animation.animatedValue as Float
            view1.translationX = translateX
            view2.translationX = translateX
        }

        shake.addListener(object : AnimatorListenerAdapter() {
            override fun onAnimationEnd(animation: Animator) {
                view1.translationX = 0f
                view2.translationX = 0f
            }
        })

        shake.start()
    }

    private fun clearSelections() {
        selectedAudioItem = null
        selectedNumberItem = null

        selectedAudioView?.let { view ->
            val linearLayout = view.findViewById<LinearLayout>(R.id.audioButtonLayout)
            linearLayout?.setBackgroundColor(androidx.core.content.ContextCompat.getColor(this, android.R.color.white))
        }

        selectedNumberView?.let { view ->
            val numberText = view.findViewById<TextView>(R.id.numberText)
            numberText?.setBackgroundColor(androidx.core.content.ContextCompat.getColor(this, R.color.button_color))
        }

        selectedAudioView = null
        selectedNumberView = null
    }

    private fun onLevelCompleted() {
        if (currentLevel < totalLevels) {
            currentLevel++
            loadLevel(currentLevel)
        } else {
            showResults()
        }
    }

    private fun showResults() {
        val finalScore = (correctActions * 10) - (incorrectActions * 5)

        val intent = Intent(this, AudioMatchingResultsActivity::class.java)
        intent.putExtra("completed_levels", currentLevel)
        intent.putExtra("correct_actions", correctActions)
        intent.putExtra("incorrect_actions", incorrectActions)
        intent.putExtra("final_score", finalScore)
        startActivity(intent)
        finish()
    }

    override fun onDestroy() {
        if (::tts.isInitialized) {
            tts.stop()
            tts.shutdown()
        }
        super.onDestroy()
    }
}

package com.timursarsembayev.danabalanumbers

data class AudioMatchingLevel(
    val pairs: List<AudioMatchingPair>
)

data class AudioMatchingPair(
    val number: MatchingItem // Используем ту же модель, что и в обычном сопоставлении
)

object AudioMatchingGameData {
    fun generateAllLevels(): List<AudioMatchingLevel> {
        val levels = mutableListOf<AudioMatchingLevel>()

        // Создаем 10 уровней
        repeat(10) { levelIndex ->
            val pairs = mutableListOf<AudioMatchingPair>()

            // Генерируем 5 пар чисел для каждого уровня
            val usedNumbers = mutableSetOf<Int>()
            repeat(5) {
                var number: Int
                do {
                    number = (1..9).random()
                } while (usedNumbers.contains(number))

                usedNumbers.add(number)

                val matchingItem = MatchingItem(
                    value = number,
                    emoji = "", // Для аудио кнопок не нужен emoji
                    isMatched = false
                )

                pairs.add(AudioMatchingPair(matchingItem))
            }

            levels.add(AudioMatchingLevel(pairs))
        }

        return levels
    }
}

package com.timursarsembayev.danabalanumbers

import android.content.Intent
import android.os.Bundle
import android.speech.tts.TextToSpeech
import android.widget.ImageView
import android.widget.TextView
import androidx.appcompat.app.AppCompatActivity
import androidx.cardview.widget.CardView
import androidx.core.view.ViewCompat
import androidx.core.view.WindowInsetsCompat
import java.util.*
import kotlin.random.Random

class AudioMatchingResultsActivity : AppCompatActivity(), TextToSpeech.OnInitListener {

    private var tts: TextToSpeech? = null
    private var isTtsReady = false

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_audio_matching_results)

        ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main)) { v, insets ->
            val systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars())
            v.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom)
            insets
        }

        // Инициализация TTS
        tts = TextToSpeech(this, this)

        setupViews()
        setupButtons()
    }

    override fun onInit(status: Int) {
        if (status == TextToSpeech.SUCCESS) {
            val result = tts?.setLanguage(Locale("ru"))
            isTtsReady = result != TextToSpeech.LANG_MISSING_DATA && result != TextToSpeech.LANG_NOT_SUPPORTED

            if (isTtsReady) {
                speakCongratulation()
            }
        }
    }

    private fun setupViews() {
        val completedLevels = intent.getIntExtra("completed_levels", 10)
        val correctActions = intent.getIntExtra("correct_actions", 0)
        val incorrectActions = intent.getIntExtra("incorrect_actions", 0)
        val finalScore = intent.getIntExtra("final_score", 0)

        // Обновляем UI с результатами
        findViewById<TextView>(R.id.completedLevelsText).text = "Пройдено уровней: $completedLevels"
        findViewById<TextView>(R.id.correctActionsText).text = "Правильных действий: $correctActions"
        findViewById<TextView>(R.id.incorrectActionsText).text = "Ошибок: $incorrectActions"
        findViewById<TextView>(R.id.finalScoreText).text = "Итоговые очки: $finalScore"

        // Определяем сообщение в зависимости от результата
        val accuracy = if (correctActions + incorrectActions > 0) {
            (correctActions * 100) / (correctActions + incorrectActions)
        } else {
            100
        }

        val (message, encouragement) = when {
            accuracy >= 90 -> Pair("Превосходно! ", "Ты отлично слышишь и различаешь числа!")
            accuracy >= 70 -> Pair("Отлично! ", "Ты хорошо сопоставляешь звуки с цифрами!")
            accuracy >= 50 -> Pair("Хорошо! ", "Продолжай тренироваться!")
            else -> Pair("Не сдавайся! ", "С каждым разом будет лучше!")
        }

        findViewById<TextView>(R.id.resultMessage).text = message
        findViewById<TextView>(R.id.encouragementText).text = encouragement
    }

    private fun speakCongratulation() {
        if (isTtsReady) {
            val correctActions = intent.getIntExtra("correct_actions", 0)
            val incorrectActions = intent.getIntExtra("incorrect_actions", 0)

            val accuracy = if (correctActions + incorrectActions > 0) {
                (correctActions * 100) / (correctActions + incorrectActions)
            } else {
                100
            }

            val phrases = when {
                accuracy == 100 -> DifferentiatedCongratulationPhrases.perfect100Phrases
                accuracy >= 90 -> DifferentiatedCongratulationPhrases.excellent90Phrases
                accuracy >= 80 -> DifferentiatedCongratulationPhrases.good80Phrases
                else -> DifferentiatedCongratulationPhrases.encouragement80Phrases
            }

            val randomPhrase = phrases[Random.nextInt(phrases.size)]
            tts?.speak(randomPhrase, TextToSpeech.QUEUE_FLUSH, null, "congratulation")
        }
    }

    private fun setupButtons() {
        findViewById<CardView>(R.id.btnPlayAgain).setOnClickListener {
            stopTTS()
            val intent = Intent(this, AudioMatchingActivity::class.java)
            startActivity(intent)
            finish()
        }

        findViewById<CardView>(R.id.btnBackToMenu).setOnClickListener {
            stopTTS()
            val intent = Intent(this, MathExercisesActivity::class.java)
            startActivity(intent)
            finish()
        }

        findViewById<ImageView>(R.id.btnBack).setOnClickListener {
            stopTTS()
            finish()
        }
    }

    private fun stopTTS() {
        tts?.stop()
    }

    override fun onDestroy() {
        tts?.stop()
        tts?.shutdown()
        super.onDestroy()
    }
}
